        Mod.SetString("sharedassets1.assets", 4016, "m_text", "Im Karamari Krankenhaus und im Puppenhaus DLC wirkt de Massenkontrolle ned so gscheid", expected: "Note that Crowd Control is less effective in Karamari Hospital and The Dollhouse"),
