        Mod.SetString("sharedassets1.assets", 4027, "m_text", "Massenkontrolle", expected: "Crowd Control"),
        Mod.SetString("sharedassets1.assets", 4045, "m_text", "Vabinda", expected: "Connect"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.0.defaultEn", "Herzlichen Glickwunsch GL Labs Mitarbeiter!\n\nDu wurdest fia unsa stolzes Eltern-Program ausgwäid worn.\n\nDu hast a Puppn kriagt, und dei Pflicht is, dassd de Sej dadrinn erziagst, de wo da gfanga is.\n\nDamit's in da Puppn drinbleibt, muaßst es bei guada Laun hoidn und Dornröschen singa. Vui von de Beta-Kandidatn warn Kinda, als se gestorben san, de wern si also ohne Groas gwiß glei an di hänga. Aba es ko sei, dass amoi a Strafe oda des Ozapfn von Geister-Energie nötig werd. Die Energie ko di gscheid aufladen, aba bitte treib's ned z'wuid, weil des am Geist ned guad duat.\n\nFalls de \"Husk\" des Ganze oablehnt oda wos bassiert, san de GL Labs unta koane Umständ schuid dadrann, obwoi des koa sinn macht aber muss aa ned.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.1.defaultEn", "Tee-Stuberl fia stoize Eltern-Helfer.\nBedienungsanleitung\n\nDes Zimmerl is dafür da, dass man an Stress abbaut und d'Geistesenergie wieda aufladt, falls de Puppn an Schwung verlorn hod. Du kannst de Funktion nutzn, indemst de Puppn auf den Sockl stäist und di genau gegniba hihockst.\n\nIn the event of husk rejection or injury, GL labs is not responsible under any circumstance.\n\nFois de \"Husks\" abgelehnt wern oder jemand zu Schadn kommt, ibanimmt d'GL Labs unta koane Umständ de Verantwortung. obwoi des a schmarrn is.\n\nVui Spass, stoizer Elternteil!", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.2.defaultEn", "GL LABS ID 1863\nEINTRAG 23\n\nMia ham Fortschritte gmocht, aba optimal war davo gar nix. Mia ham a System entwickelt, um de Geista herzuwinken und einzusperrn, aba mia ham bis jetz no koa gscheide Hülln gfundn. Wia da Direktor sei Dochta s'erste Moi wieda vo de Toten herg'hoit hat, warma olle ganz staunig, aba lang is' ned do bliebn. Ohne ebbas Gscheids, wo de Geista an d'Erdn bindi, verflüchtigen de si oafoch wia da Rauch.\n\nZ'erst hamma's mit ganz normale Glasl, Vasn und so am Zeig probiert, aba de behälter ham de Geista in eanere Fähigkeitn total eigschränkt. A bisserl an Erfolg hamma ghabt, wia mia menschenähnliche G'fäß hergnumma ham, aba de Selln hängan imma no an de physikalischen Schadn vo dene behälter und desweng san's oafoch vui zu zerbrechlich.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.4.defaultEn", "GL LABS ID 1863\nEINTRAG 24\n\n\nMia ham sakrische Probleme damit, oan vo de stärkan Gspenstn ozusperrn. De Puppn, de mia als G'fäß hernehma, ziagts imma wieda auseinander und geht hi, so dass mia den Geist jeds Moi wieda komplett nei heruafa miassn. Rein theoretisch sollt de Größn vom Behälta ja ganz wurscht sei, aba uns wird gsogt dass ois vui zu eng und zu kloa is.\n\nDesweng hamma's erst amoi hinta a Notfoi-Sperrdia weggasperrt.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.5.defaultEn", "Den ganzn Dog war i a braves Mädl und hob no ma biebel glesn. Aber als ma Vada hoam kemma is, war er total meschugge. Desweng hab i mi in mei Zimmerl vergrom, bis er weg war. Und dann hab i eahm um 5:45 mitten ins Gsicht gschossn.\n\nSei Gwehr war so schee glänzend und sauber, und sei Gsicht war danach ganz gammelig, matschig und weich. I hätt gern no mehr Leit erschossn, aber mei Muada hat mi so miad gmacht. Jetz bin i in a komisches Haus mit de ganzn seltsama Weißkittel-Leit und de gebn mia oafoch koa Gwehr mehr.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.6.defaultEn", "Mai Liabe Monica,\nObwois schwar war, hob i dei bittn respektiert und di ruhn lossn. I vamiss di jeden dog. I vamiss di. so sehr.\n\nI werd no versucha dei dochda zu retta. I woass des is ned wos du woitest, aba steck scho gscheid in da scheisse. Sie is so nah, I muass irgendwia a weg finda damit sie hier bleibt. \n\nDu bist mei Stern am Himme,", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.7.defaultEn", "GL LABS ID 1863\nEINTRAG 34\n\nDamit de Puppn bei Laun bleibn, hamma den 'Party-Raum' do hergricht. Mia ham sogoa extra an Geist herg'hoid, der's a bisserl unterhaltn soi, aba des Experiment is wirkli ins wossa gfalln.\n\nDe Puppn hassen den Ort da herinnat und san total g'schreckt, wia's den 'Clown' fei nur oschaung. I hob mir de Unterlang bstellt, wia de den ibahaubt g'fundn ham, und wia's ausschaut, wolltn de eigentlich an ganz an friedlichen, lustigen Menschengeist herbeinrufa, stattdessen hamma jetz a ganz andara kas do.\n\nSchaugt aus wia a Mensch, duat wia a Mensch, Zur Sicherheid hamma a Gitter drumrum baut. Was um Himmelswuin ham de da bittschee herg'hoit?\n", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.8.defaultEn", "GL LABS ID 1210\nEINTRAG 189\n\nI sieg sie. Ganz am Rand vo meim Aug.\nSobald i sie direkt oschau, zuckts und kimmt auf mi zua. Manchmal hia i sie fei hinta mia schnaufn.\n\nWia bin i bloß do herg'loffa? Is des unsane Straf dafia, dass mia den Tod ned ham gelten lassn? I hob doch allweil bloß Befehle befolgt.\nMei blinde Treue hat mi do herbracht... vielleicht hilft mia d'Blindheit ja aa wieda naus.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.9.defaultEn", "GL LABS ID 1210\nEINTRAG 189\n\n\nI", expected: "GL LABS ID 1210\nLOG 189\n\n\nI", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.10.defaultEn", "GL LABS ID 1863\nEINTRAG 46\n\n\nDe KIRA-Mega Drive is etz a totaler Klump.\n\nMia ham vui zu vui Geista herg'hoit, des packt de Maschinn einfach nimma. Sogoa wenn mia de wieda z'riackschicka, haut's uns vielleicht des ganze Tor zamm! Desweng hob i jetz 3 von de Ritual-Kerzn nunter im Erd-Kella gbracht. Des sollt den Beschwörungs-Schmarrn erst amoi aufhoitn.\n\nSpooky wird wahrscheinlich irgendwen losschicka, dass de des wieda herg'hoit, aba is ned mei Bier.\n\nChancen stehn eh aa guad, dass derjenige do druntn ned amoi ibalebt.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.11.defaultEn", "Da Siegl is fast fertig, und dann kannste wieda zriackkemma.\n\nDamits aa geht, braacht's an Albtraum. Also opfere i meinen.\n\nDa gliche Albtraum, der di uns gnumma hod, bringt di wieda zriack.", expected: "The seal is almost complete, and then you can return to me. \r\n\r\nIt requires a nightmare to work. So I will surrender mine.\r\n\r\nThe same nightmare that took you from us, will now bring you back.\r", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.12.defaultEn", "i hob an Bock gschossn i\nwoass des und du aa.\n\n\nI hoff du bist ned zu zwieder auf mi.\nDea Hofbräu Minga wars ned. Mei i woid hoid dei Vergebung.\n\n\nMei Liebe fia di hod mi krank gmacht, und am end hob i da nur dei Lem und ned-Lem gmaust.\nBitte geh weida, und bleib bei da Monica.\n\n\nI mecht mi am liabsten vergroam vor Scham.", expected: "I always wanted to tell you.\nHow that night really ended.\n\n\nBut I couldn't. Because you were gone.\nI need your forgiveness. That's why I wanted you back at any cost.\n\n\nBut in the end I robbed you of both life and unlife. Please go on, and be with Monica.\n\n\nI'm sorry.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.13.defaultEn", "GL LABS ID 1210\nEINTRAG 187\n\nDe Geista wern fei grantig, mia miassn allweil wieda Rituale durchziang, damit mia de im Griff bheitn.\n\nWenns wieda narrisch wern, muass ma Druck auf de \"Husk\" ausiabn, wo da Geist drinnat steckt.\n\nVergiss ned, dass de Puppn koane echten Menschn san.", expected: "GL LABS ID 1210\nLOG 187\n\n\nThese spirits get so temperamental, we keep having to perform rituals to keep them in check.\n\n\nWhen they act out it's necessary to inflict pressure on the husk inhabited by the spirit.\n\n\nDon't forget that these dolls are not real people.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.14.defaultEn", "GL LABS ID 54\nEINTRAG 809\n\n\nHoffentli werd i jetz, wo des Puppn-Projekt-Schmarrn vorbei is, boid wieda an die Oberflächn-Anlag versetzt. Intressant war's ja scho, aba ganz ehrlich hob i jedn Dog Angst um mei Lem. Des is jetz ned groad die beste Arbeitsplotzsicherheid.", expected: "GL LABS ID 54\nLOG 809\n\n\nHopefully now that the Doll Project is over, I'll get transferred back to the surface facility soon. It's been very interesting, but I generally fear for my life everyday. That's not ideal job security.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.15.defaultEn", "GL LABS ID 1863\nEINTRAG 32\n\nMia hom d'Idee mit da Puppn aufgem, wo mia des Versuchskaninchen an a physischn Gegenstand binden woitn. Stattdessn hobma ia Sej jetz direkt im Schloss sejba eisperrt. Ia Fähigkeitn do herinn im Labor miassn unvorstellbar sei. Da Herr Direktor wiad mit'm Ergebnis vo seim Opfer fei mehr ois zfriedn sein.", expected: "GL LABS ID 1863\nLOG 32\n\n\nWe abandoned the doll idea of tethering the subject to a physical object and instead we sealed her spirit within the mansion itself. Her abilities within the facility should be incredible. The director would be pleased with the outcome of his sacrifice.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.16.defaultEn", "GL LABS ID 54\nEINTRAG 67\n\nI hob's no koam erzäid, aba i glaab, in der Bude spukt's. Da drinnad gibts de ganze Zeid so komische, unheimliche Geraische. Des klingt wia a Jammarn, aba aa wia Woa, woasd? so a Woaman. Und do war des oane Buildl, wo i de ganze Zeid higstarrt hob, i denk des hod si vaändert nach a Zeid.", expected: "GL LABS ID 54\nLOG 67\n\n\nI haven't told anyone yet, but I think this place is haunted. There are like, these strange woaning sounds all the time. Like a moan but also like woah, you know. So Woaning. And there was this painting that I kept staring at, that I think was changing.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.17.defaultEn", "A Puppn is wos Ewigs. Schaut aus wia a Kolleg, aber gans makellos gschaffn. Unsterblich und staad. Und fei drent dod, weil koa Seel drin is.\n\nA passends Symbol und womöglich a ganz nützlich's Werkzeig fia unsa Ziel do.\n\nBoid hob i di wieda bei mia, mei Schatz. Aba zearscht muass i sicherstäin, dass di des Ganze ned eisperrt.", expected: "A doll is a timeless thing. In the shape of a human but created perfect. Immortal and unmoving. Yet hollow, devoid of soul.\n\n\nA fitting symbol and possibly usable device for our goals here.\n\n\nSoon I will have you back, my dear. But first I must make sure it won't constrict you.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", -2798266528036338404, "kvps.Array.18.defaultEn", "Nach dea ganzn Forscherei und de Experimente hobma am komplett foischn Ort gsuacht. De Puppn hom uns eigentlich bloß abglenkt. Mei Herz homs ned trösta kenna und fia di zum Eiziang war's aa ned. Genau desweng bist du ned zu mia zriackkumma.\n\nAba jetz hob i wos anders gfundn.\n\nA Relikt aus da oidn Kinigreich-Zeit, des wo de Geista an d'Ern feistmacht. Obwoi des urspriangli fia wos richtig Biass hergnumma worn is, werd i des fia di nutzn.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 3612903640223546060, "closeText.defaultEn", "Wegrama", expected: "Close", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 3612903640223546060, "mapText.defaultEn", "Hausplan", expected: "Map", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 3612903640223546060, "noMapText.defaultEn", "Es gibt do koa Hausplan ned", expected: "No map of area", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.0.defaultEn", "D'Luft do herrin riacht total\nno Moder und Schimmel.\nDei Lungen duan si richtig\nschwer beim Eianschnaufen.\nAn dem Ort da heilen\ndei Wunden fei fast\ngoar ned.", expected: "The air here is heavy with must\nand mold. Your lungs seem to\nstruggle as you inhale. Your\nability to heal is hindered in\nthis place.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.1.defaultEn", "Is zuagschpeart.", expected: "It's locked.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.2.defaultEn", "Du hast’s aufdoan.", expected: "You unlocked it.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.3.defaultEn", "Dei Geist wurde aufgschriem.", expected: "Your spirit has been recorded.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.4.defaultEn", "I ko ned z'ruckgehn.", expected: "I can't go back.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.5.defaultEn", "Irgendwia ziaght di de Puppn o. wuis de Puppn hernemma?", expected: "Something about this doll draws you to it. Pick up the doll?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.6.defaultEn", "aafhem?", expected: "Pick her up?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.7.defaultEn", "obisetzn?", expected: "Set her down?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.8.defaultEn", "Jo", expected: "Yes", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.9.defaultEn", "Naa", expected: "No", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.10.defaultEn", "Scho a komisches podest ned?", expected: "What a strange pedestal", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.11.defaultEn", "Is auf d'andere Seitn zuagsperrt.", expected: "It's locked from the other side.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.12.defaultEn", "Hos'd a Hausplan. ums zu seng, schau obi und verwends.", expected: "You picked up a map. To use it, look down and Interact.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.13.defaultEn", "Hosd den Bolznschnaida eig'sackt", expected: "Picked up the Bolt Cutters", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.14.defaultEn", "De Bodnuhr geht auf", expected: "The Clock Opens", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.15.defaultEn", "D’Tir is total fest mit Stacheldraht eigwickelt. Magsts trotzdem aufmachen?", expected: "The door is wrapped tightly in barbed wire. Try to open it?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.16.defaultEn", "D’Tir is total fest mit Stacheldraht eigwickelt. Bolznschnaida nutzn?", expected: "The door is wrapped tightly in barbed wire. Use the bolt cutters?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.17.defaultEn", "D’Tir wird zuaghaitn. Bolznschnaida nutzn?", expected: "The door is held shut. Use the bolt cutters?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.18.defaultEn", "Da Draht schneidt dir voll in d'Händ nei, des bluat wia d'Sau!.", expected: "The wire slices through your hands.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.19.defaultEn", "Zwick! Und herunt is da Draht!", expected: "The wire cuts apart.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.20.defaultEn", "Da drin dad si da Mozart im Grab umdrahn!", expected: "It sounds out of tune...", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.21.defaultEn", "Schliasse für'n West-Flügl g'fundn.", expected: "Picked up the west wing key.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.22.defaultEn", "Da is a Loch. Bin i jetzt komplett deppat und pratz da nei, wo i nix verloren hab?", expected: "There is a hole here. Reach inside?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.23.defaultEn", "Auf oamoi krallt si a miese sau dei Hand.", expected: "Something grasps your hand.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.24.defaultEn", "I braachat a verflixte zugangskartn!", expected: "Access Card Required", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.25.defaultEn", "Hihocka?", expected: "Sit down?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.26.defaultEn", "Aufstehn?", expected: "Get up?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.27.defaultEn", "Uhrn-Aufziach-Schliasse g'fundn", expected: "Winding Clock Key Picked Up", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.28.defaultEn", "Hosd de schwoaze Kerzn aufghobn.", expected: "You picked up the black candle.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.29.defaultEn", "A schwoaze Kerzn.", expected: "It's a black candle.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.30.defaultEn", "Heilige Maria Gottes! Was is’n des für a Riesn-Puppn? Die hängt da an silberne Hak’n rum und es hat a Windradl aus Metall draufg'klebt. Runterreißen?", expected: "A life sized doll hangs here by several silver hooks. There is a metal pinwheel piece glued to them. Tear it off?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.31.defaultEn", "Metall-Windradl-Teil mitg'nomma.", expected: "Picked up a metal pinwheel piece.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.32.defaultEn", "Wos für a komisches Kunstwerk… na ja, in so am Irrenhaus is des Unnormale ja normal.", expected: "It's some sort of strange sculpture.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.33.defaultEn", "A schwere Metallplattn iba a schmoin Loch. Sieht danach aus, als ob man d'Plattn zuschieben könnt. Mogst es wegschiam?", expected: "A heavy metal plate over a narrow hole. It looks like it can slide shut. Move the plate?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.34.defaultEn", "GL LABS Zugangskartn aufghobn.", expected: "GL LABS keycard picked up.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.35.defaultEn", "Es gibt koa Zeid ned!", expected: "There's no time!", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.36.defaultEn", "Des ding wui a Zugangskarte", expected: "Access Card Required", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.37.defaultEn", "Solang do Hokuspokus laaft, is d’Tir zammbrammelt. Basta.", expected: "The door is sealed during the ritual.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.38.defaultEn", "Da fehlt a Kerzn.", expected: "There's a candle missing.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.39.defaultEn", "Da wär a Platz für a Kerzn. Aber d’Kerzn fäit. Mogst a Kerzn histäin?", expected: "There's a spot for a candle. The candle is missing. Place a candle?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.40.defaultEn", "is hi.", expected: "It's broken.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.41.defaultEn", "Des Siegel ko man obischoitn. Aber wenn i des dua, muss i mi vom Puppen-Geist verabschieden. Danach gibt’s koa Zurück mehr. Soll i dem Trauerspiel a End setzen?", expected: "The seal can be turned off. But if I do this, I'll have to let the doll spirit go. There's no going back after this. End the nightmare?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.42.defaultEn", "dafia braachst a Puppen-Geist!", expected: "Doll spirit required.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.43.defaultEn", "Der Zug fährt wohl wieder nauf. Wennst Glück hosd und des ned die DB is,\nbewegt sich das Teil sogar do hi. Di Kistn oschoitn?", expected: "This train looks like it goes all the way back to the surface. Start the train?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.44.defaultEn", "Da herunt pennt einer gscheit. legst eam d’Waffn unter d'Nasn?", expected: "Someone is sleeping here. Plant the gun on them?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.45.defaultEn", "Jo", expected: "Yes", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.46.defaultEn", "Naa", expected: "No", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.47.defaultEn", "Vielleicht wird d’elektrische Wand sie bewegn?", expected: "Maybe the electric wall will move them?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.48.defaultEn", "Da liegan lauter kaputte Puppenteile und a Paar zammg'legte Plastik-Handl, die schaut so aus, als ob's was festhoitn. De san a bissal zammg'schmoizn. Mogsts eine stecka?", expected: "There are several broken doll parts and a pair of plastic clasped hands that appear to be holding something. They are slightly melted together. Pick it up?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.49.defaultEn", "A paar Plastik-Pfoten g'fundn.", expected: "Picked up some doll hands.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.50.defaultEn", "Schmelzofa aufdoan?", expected: "Open the furnace?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.51.defaultEn", "Schmelzofa zuadoan?", expected: "Close the furnace?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.52.defaultEn", "d'Plastik-Puppenhandl eine doan?", expected: "Put the plastic doll hands in?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.53.defaultEn", "D'Puppenhandl san komplett dahi, ma siagt a kloane schliassal, wuist n' mitnehma?", expected: "The doll hands have melted away, revealing a small key. Pick it up?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.54.defaultEn", "Den Hebel ziagn?", expected: "Pull the switch?", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.55.defaultEn", "Da is Schlus mit lustig, der Hebel rührt si koan Zentimeter.", expected: "The switch is locked in place.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.56.defaultEn", "Nachdem der Bapperl vom Siegel herunt is, kinnan de ganzn Gsperstl, die im Schloss eingesperrt waren, weiterziagn. Und weil s'Teifelsloch jetzt gscheit zua is, verziagn si die ganzen Grusel-Viecher aa langsam. Spooky hod Leine gzogen und hockt jetzt selig bei ihre Alten. trotz dem ganzen Gschiss und Gschaua im Irrenhaus hosd am End a Ruah reingebracht. Sauber g'macht!", expected: "With the seal broken, the spirits trapped within the mansion can now go on. And with the hellgate shut, the terrors that seeped through begin to fade away. Spooky has moved on, and rests with her parents now. Somehow, despite all the horror within the mansion, you brought peace to it all.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_data", 6617335911002983813, "kvps.Array.57.defaultEn", "Jetzt, wo des Siegel brochn is, kinna d'Seeln, die im Schloss g'fanga warn, endlich ausse. Aber des Tor zur Hölln is sperrangelweit offn bliem. A Welle voller Schreckn bricht etzala iwa uns eine. Die Ausgeburten, die früher hinter de Mauern eing'sperrt warn, krampfan si jetzt nauf an die Oberflächn. Du hast di zwar grett't awa da draußen wartet a Welt voia Höllnqualn auf di.", expected: "With the seal broken, the spirits trapped in the mansion can go free. However the gate to hell was left open. A flood of terror spills outward. The horrors that were once contained within the mansion can now reach the surface. You have escaped into a doomed world.", inner: "CAB-72c1290f8994fae801a539e0c9ce5405"),
        Mod.SetString("StreamingAssets/doll_scenes", 16, "m_text", "Rasende Qual, meschugenna Verstand!\nBluat muass fliaßn, Knocha wern z'mahln!\n\nDes Fleisch g'fressen, damit de Zeit weidagacht,\nGewoit erzeugt Gegengewoit!", expected: "Frenzied torment, distorted Mind!\nBlood to spill, bones to grind!\n\nThe flesh it takes for time to wind\nEye for eye makes all turn blind", inner: "BuildPlayer-FrenzyKillScene"),
        Mod.SetString("StreamingAssets/doll_scenes", 16, "m_text", "Säun aus gschmolzenem, verdrehtem Fleisch\nsan ausm Bodn kemma wia a Ameisn-Haufn,\nder von innen her am Kocha war.\n\nDa Blitz is schreiand durch an \nHimme gfahrn, aba er is ned vergaunga\ner hod eher schwarze, marmorierte Narbn\nquer iaban Horizont hinterlassn.\n\nD'Luft is schwarer und schwarer worn\nbis s' zu ana festen Massn worn is\nde si unta deine Fiaß gwundn hat.\n\nDu hosd an Atem oghaltn.\nDu hosd deim Herrgott nimma traut.\nDu hosd dia seiba nimm traut.", "Pillars of molten twisting flesh\narose from the ground like an\nant nest that was boiling from\nthe inside. \n\nLighting screamed through the\nsky but did not dissipate and\ninstead left black marbled scars\nacross the horizon.\n\nThe air grew heavier and heavier\nuntil it too became solid mass\nthat writhed beneath your feet. \n\nYou held your breath. \nYou did not trust your eyes.\nYou did not trust your self.", inner: "BuildPlayer-SkunnyPuppi"),
        Mod.SetString("StreamingAssets/doll_scenes", 31, "m_text", "Du bist so a Depp!", expected: "You are a fool.", inner: "BuildPlayer-WireKillScene"),
        Mod.SetString("StreamingAssets/doll_scenes", 2966, "introLines.Array.0", "I find die Worte ned.", expected: "It was a nightmare.", inner: "BuildPlayer-DOLL_Nightmare"),
        Mod.SetString("StreamingAssets/doll_scenes", 2966, "introLines.Array.1", "Die Nacht, wo i wie\na Wildviech reagiert hab", expected: "The night I saw the devil.", inner: "BuildPlayer-DOLL_Nightmare"),
        Mod.SetString("StreamingAssets/doll_scenes", 2966, "outroLines.Array.0", "I ko  di ned verlian.", expected: "I can't lose you.", inner: "BuildPlayer-DOLL_Nightmare"),
        Mod.SetString("StreamingAssets/doll_scenes", 2966, "outroLines.Array.1", "I bring di scho zriack.", expected: "I will bring you back.", inner: "BuildPlayer-DOLL_Nightmare"),
        Mod.SetString("StreamingAssets/doll_scenes", 3495, "lines.Array.0.subtitle.defaultEn", "hey Spetzl...", expected: "Oh hey...", inner: "BuildPlayer-DOLL_LAB"),
        Mod.SetString("StreamingAssets/doll_scenes", 3495, "lines.Array.1.subtitle.defaultEn", "I mogs hier ned.", expected: "I don't like it here.", inner: "BuildPlayer-DOLL_LAB"),
        Mod.SetString("StreamingAssets/doll_scenes", 3495, "lines.Array.2.subtitle.defaultEn", "Schleich di am bestn.", expected: "You should probably just leave.", inner: "BuildPlayer-DOLL_LAB"),
        Mod.SetString("StreamingAssets/doll_scenes", 3495, "lines.Array.3.subtitle.defaultEn", "Also Sapallott! hier is nix fia di!", expected: "There's nothing for you here.", inner: "BuildPlayer-DOLL_LAB"),
        Mod.SetString("StreamingAssets/doll_scenes", 3495, "lines.Array.4.subtitle.defaultEn", "... Jessas Maria -_-", expected: "Just leave.", inner: "BuildPlayer-DOLL_LAB"),
        Mod.SetString("StreamingAssets/doll_scenes", 10611, "lines.Array.0.subtitle.defaultEn", "Oh hey... äh...", expected: "Oh hey... Uh...", inner: "BuildPlayer-DOLL_NW"),
        Mod.SetString("StreamingAssets/doll_scenes", 10611, "lines.Array.1.subtitle.defaultEn", "I war am überleng,", expected: "I was thinking,", inner: "BuildPlayer-DOLL_NW"),
        Mod.SetString("StreamingAssets/doll_scenes", 10611, "lines.Array.2.subtitle.defaultEn", "dass d' etwas hilfe megst.", expected: "you might want some help.", inner: "BuildPlayer-DOLL_NW"),
        Mod.SetString("StreamingAssets/doll_scenes", 10611, "lines.Array.3.subtitle.defaultEn", "Also, hab i de ganzn Puppen,", expected: "So, I moved all those dolls,", inner: "BuildPlayer-DOLL_NW"),
        Mod.SetString("StreamingAssets/doll_scenes", 10611, "lines.Array.4.subtitle.defaultEn", "aus'm weg g'rammt! :D", expected: "out of the way! :D", inner: "BuildPlayer-DOLL_NW"),
        Mod.SetString("StreamingAssets/doll_scenes", 10611, "lines.Array.6.subtitle.defaultEn", "Wünsche dir viel Gaudi! OwO", expected: "Well, have fun!", inner: "BuildPlayer-DOLL_NW"),
        Mod.SetString("StreamingAssets/doll_scenes", 11053, "lines.Array.0.subtitle.defaultEn", "Oh habe!", expected: "Oh hey!", inner: "BuildPlayer-DOLL_1F"),
        Mod.SetString("StreamingAssets/doll_scenes", 11053, "lines.Array.1.subtitle.defaultEn", "Do bist also.", expected: "There you are.", inner: "BuildPlayer-DOLL_1F"),
        Mod.SetString("StreamingAssets/doll_scenes", 11053, "lines.Array.2.subtitle.defaultEn", "hab mi scho g'frogt, wo du abbliam bist.", expected: "I was wondering where you were.", inner: "BuildPlayer-DOLL_1F"),
        Mod.SetString("StreamingAssets/doll_scenes", 11053, "lines.Array.3.subtitle.defaultEn", "Da war’s mal schee zum Wohna.", expected: "I had forgotten about this place.", inner: "BuildPlayer-DOLL_1F"),
        Mod.SetString("StreamingAssets/doll_scenes", 11053, "lines.Array.4.subtitle.defaultEn", "Hier san einige Seelen gfanga.", expected: "So many tortured souls are here.", inner: "BuildPlayer-DOLL_1F"),
