        Mod.SetString("StreamingAssets/em_scenes", 22, "m_text", "HINTER DERA PFORTN ZUM HIMMELREICH LIEGT\nD'WAHRE WÄID.\nA WÄID, SCHEENER ALS JEDER DRAM...\nA WÄID WO DA HERRGOTT ALL DEI\nDIAFSTN SEHNSÜCHTE WAHR MACHT.\nA WÄID VOLLER GNAD’ UND\nDA GÖTTLICHEN PRACHT VON ALLE HEILIGEN...\nA WÄID WO D'HEILIGEN IM CHOR SINGEN,\nBLOSS UM DI IN IHRA GÖTTLICHEN MITTN AUFZUNEHMA.", expected: "BEYOND THAT DOOR IS ANOTHER WORLD.\n\n\nA WORLD MADE OF DREAMS...\nA WORLD WHERE ALL YOUR FANTASIES HAVE COME TRUE.\nA WORLD FULL OF EVERYONE'S SICK FANTASIES.\nA WORLD LUSTING TO INCLUDE YOU.", inner: "BuildPlayer-UnknownSpec3Killscreen"),
