        Mod.SetString("StreamingAssets/kh_data", -80081508241453208, "kvps.Array.26.defaultEn", "es gfühlt si warm o.", expected: "It feels warm.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 3316686253279040984, "kvps.Array.0.defaultEn", "Dr. Ludwig\r\nOnkologe\r\n\r\n\r\nDea Patient hod erhiate Depressionen\r\ngzeigt nachdem dea mitbekomma hod\r\ndes ea a unheilbare Krankheit hod.\r\n\r\nI hob a Antidepressivum verschriam\r\num des zu bessan aba mia wurd späda\r\ngsogt des i des abgebrochn habe.\r\n\r\nI ko mi ned erinnern des i des gmacht\r\nhob. Hoban di an Vogel? oda bin I \r\nnarrisch?", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 3316686253279040984, "kvps.Array.1.defaultEn", "Dr. Ludwig\r\nOnkologe\r\n\r\n\r\nScheind so als ob des andre \"I\" ihm griaße\r\nmengn o Halluzinogen geban hod. \r\n\r\nSe ham de Depressionen vaschlimad und ea\r\nschreit und tut sei Angst ausdrückn\r\nwos aa zufällig ausschaugt.\r\n\r\n\r\nI hob probiert a Dialysegerät zu nutzn\r\num de Drogn zu wegdoan, aber bringt\r\nfei ned a moi wos, Jo mei!", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 3316686253279040984, "kvps.Array.2.defaultEn", "Dr. Korbinian\r\nHepatologe\r\n\r\n\r\nI wurd grod informiert des dea vorgang \r\nwo bei es rum geht de Leber vom Patient'n\r\nzu entfernen tödlich sei ko.\r\n\r\nI woas ned wieso...\r\nWarum ham ma sei Leber entfernt?\r\n\r\nEs gibt koane spende anfragn und dea hod\r\nBesserungen gzeigt.\r\n\r\nDea OP-Personal hom mi erzäid des i \r\nbefohlen hob sei Leber zu entfernen\r\nfia a notfall Transplantation, und des\r\nwuideste is des I es gfundn hob...\r\n\r\nI hob sei Leber gfundn, sei ganza Leber.\r\n\r\nDuad no wie bläd aaf ma Disch verrota...", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 3316686253279040984, "kvps.Array.3.defaultEn", "Dr. Shienazugawa\r\nHämatologe\r\n\r\n\r\nDea Patient is ned vo dea Blutverlust\r\nwieder fit gworda.\r\n\r\nI hob des gfühl des a Monster in ma Birne\r\nis und es versucht mi weg zu schubsen \r\nwährend es an etwos oabart.\r\n\r\nI bin in den Patienten Raam aufgwocht\r\nwo bei I iba iam gstandn bin während\r\na Arterienkatheter im Patienten woa,\r\nlässte iam nur am boden ausbluadn.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 3316686253279040984, "kvps.Array.4.defaultEn", "Pflegefachfrau Sophia\r\nBericht \\#404\r\n\r\n\r\nScheind so als ob ma Patiente valiern\r\nwega 'chirurgische Komplikationen'\r\nvui iftas ois normal.\r\n\r\nWas ham de Doktorn gdoan?\r\n\r\nHälfte vo dea Eingriffe wirka sau\r\nunnötig. I woas des se iba mi san\r\nund vui wissen des i ned woas,\r\naber des kimmt ma spanisch vor.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 3316686253279040984, "kvps.Array.5.defaultEn", "Pflegefachfrau Sophia\r\nBericht \\#405\r\n\r\nI bin in Ohnmacht gfoin, \r\nois i auf d'Arbeit gfahrn bin.\r\n\r\nZuerst fahr i no ganz normal de Straß \r\nnunda und auf oamoi, so wos konnst \r\ngar ned ausdenka, steh i scho draußn \r\nvor meim Auto und schau aaf a tote Katz \r\nnunda. Wahrscheinlich hob i’s mit’m Auto \r\ndawischt und mi hinteher scheiße gfuillt.\r\n\r\nDes Buidl vo dera Katz verfolgt mi bis \r\nheid und lasst mi nimma aus.\r\n\r\nWia hob i des Viech nur so dawischt kinna, \r\ndass’n den Körper sau komplett verdraht hod?", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 3316686253279040984, "kvps.Array.6.defaultEn", "Pflegefachfrau Sophia\r\nBericht \\#405\r\n\r\nEtwos Unheimliches lauert ganz tiaf \r\ndrin in meim Unterbewusstsein.\r\n\r\nEs schreit und wui, dass i \r\ndirekt in d'Höll nunda marschiar.\r\n\r\nVadda unsa im Himme, vagib uns \r\nunsa Schuid. Und fia uns ned in \r\nVersuachung, sondern erlös uns \r\nvo dem Biasn...", expected: "Nurse Tanaka\r\nReport \\#406\r\n\r\n \r\nSomething sinister is beating on the wall \r\nof my subconscious,\r\n\r\nbeating like a war drum motioning me to \r\nmarch down into Hell.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 3316686253279040984, "kvps.Array.7.defaultEn", "Pflegefachfrau Sophia\r\nBericht \\#407\r\n\r\n\r\nI war des ned...\r\nI schwör’s beim Berch \r\nund beim Lem.\r\n\r\nEs miagn vielleicht mei Körper und \r\nmeine Händ gwen sei, aber i woas \r\nganz genau, dass i des ned war.\r\n\r\nHerr, nimm mei Hand und fia mi aus \r\nda Finsternis, damit mei Seel wieder \r\nrein werd.", expected: "Nurse Tanaka\r\nReport \\#407\r\n\r\n \r\nIt wasn't me..\r\nI swear it wasn't.\r\n\r\nIt may have been my body and my hands,\r\nbut I know it wasn't me.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 3316686253279040984, "kvps.Array.8.defaultEn", "Pflegefachfrau Sophia\r\nBericht \\#408\r\n\r\n\r\nI hob herausgfund wie ma sie\r\naufhoitet.\r\n\r\nSchau sie san in ma Kopf und kinnan\r\nmi fia a bestimmte Zeid kontrollieren.\r\n\r\nAber wenn i ständig de Radiologie\r\nMaschine benutz um mei Birne mit \r\nStrahlung zu bestrahlen dann gengan\r\nsie fia a weile weg.", expected: "Nurse Tanaka\r\nReport \\#408\r\n\r\n \r\nI found out how to stop them.\r\n\r\nYou see they are in my head and can \r\ncontrol me for a time.\r\n\r\nBut if I  kee p using the  radiology \r\nma chine to dose my head with radiation \r\nthen they  go  aw ay for a while.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 3316686253279040984, "kvps.Array.9.defaultEn", "Es duat ma so leid, mei kloanes Engel.\r\n\r\nI hob echt versucht, dass i den \r\nTypen hass, der di uns weggnumma hod. \r\nAber am End vom Dog konn i mi bloß no \r\nselber hassen.\r\n\r\nDu hosd es scho immer gmogt, \r\nauf d'Oktoberfest zu genga, vor allem \r\nweil’s di dena scheena und neier\r\nDirndl so bewundert hom. Du woitest \r\nunbedingt a Bier trinka, da hob i \r\ngsagt: 'Guad, aber bloß a alkoholfreies!' \r\nGschmeckt hod’s da, aa wenn ma’s sonst ned \r\noft g’kaaft hom. Du hosd gfeiert und gtanzt \r\nois Dinge, auf de i so sakrisch stolz bin.\r\nAber dieser Bua hod ohne Zweifel vui zu \r\nfuchsteufelswuid auf deinen Feuerwerkskörper \r\nreagiert. Aber mia kinna oane Person mit \r\nPTBS halt ned de ganze Schuid gem.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 3316686253279040984, "kvps.Array.10.defaultEn", "I hass mi selber für des, was i do\r\n dua, aber i ko einfach \r\nnimmer lang warten.\r\n\r\nDei Muddi setzt zwar a tapfers Gsicht aaf, \r\naber i woas ganz genau, dass sie des aa so wui.\r\n\r\nI mach guade Fortschritte, damit i di wieder \r\nzruckbring, aber es schaut so aus, ois ob des \r\nbloß fia an kurzn Moment funktioniert sogar \r\nwenn i de Schwellenwerte länger einstell.\r\n\r\nHeid hob i de Antwort gfundn. Ma braucht a \r\nzweits Gerät, damit ma de Seel an d’Erden \r\nbindt, wenn’s erst amoi zruckbracht worden is. \r\nI woas, des klingt jetzt makaber, aber i werd’s \r\ndann scho wieder ausschoitn und di zarick in \r\nHimme schickn, nachdem dei Muddi und i di \r\nendlich wiedagseng hom.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.0.defaultEn", "I woas ned, wia’d so weid unta kemma bist.", expected: "I don't know how you got all the way down here.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.1.defaultEn", "I hob gar nimma gwusst, dass do unta no Zimma san.", expected: "I didn't even remember there were rooms down here.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.2.defaultEn", "Na ja, vui Glück!", expected: "Well, good luck!", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.3.defaultEn", "Deser Oad is vui greßa ois i gdocht hob.", expected: "This place is much bigger, than I thought it would be.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.4.defaultEn", "Des is scho sehr...\nInteressant.", expected: "It's very...    Interesting.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.5.defaultEn", "Mach weida Rekrut, und i bin sicha dass du des schoffst.", expected: "Well keep going recruit, and I'm sure you'll make it out.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.6.defaultEn", "Möglicherweis...", expected: "Maybe...", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.7.defaultEn", "Ah, do bist ja!", expected: "Oh, there you are!", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.8.defaultEn", "I glaab do gibts no a boa vasteckte Sachan.", expected: "I guess there are still some hidden things down here.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.9.defaultEn", "Mach hoid weida...", expected: "Well keep going...", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.10.defaultEn", "Und mia schaugn moi wos bassiert.", expected: "And we'll see what happens.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.11.defaultEn", "Jo...", expected: "Yeah...", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.12.defaultEn", "Pfiat di!", expected: "Cya later!", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.13.defaultEn", "Wie’s ausschaut, hoast de an andern Schliff.", expected: "You seem different from the others.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.14.defaultEn", "I bin scho sau long do... I hob scho so vui vagessn.", expected: "I've been here so long... I've forgotten so much.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.15.defaultEn", "Deser Oad... er muaß gschlossn wer’n.", expected: "This place... It needs to be shut down.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.16.defaultEn", "I woaß, dass du es schaffen kost, beeil di bloß. Du bist etzad so nah dro.", expected: "I know you can do it, just hurry. You're so close now.", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.17.defaultEn", "Bitte...dua...mi...ned...weh", expected: "Please...don't...hurt...me", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_data", 8212225183974745997, "kvps.Array.18.defaultEn", "Lass mi einfach in Ruah!", expected: "Just leave me alone!", inner: "CAB-6805cb9fac0ab311a5bcef2cccca4992"),
        Mod.SetString("StreamingAssets/kh_scenes", 25, "m_text", "Steh net vor Samsdog auf", expected: "Don't get up before Saturday.", inner: "BuildPlayer-MonsterSixKillscreen"),
        Mod.SetString("StreamingAssets/kh_scenes", 22, "m_text", "Finstare Würma schrein in meim Hirn.\nSie flehn mi o, dass i wieda friss.\nHerzn, Bluad, Galln und Erdn.\nI muas mi nährn, damit da Aufruhr aufhört.\n", expected: "Dark worms scream inside my brain.\nBegging me to eat again.\nHearts, and blood, and bile, and soil.\nI must consume to end turmoil.\n", inner: "BuildPlayer-MonsterFourKillscreen"),
        Mod.SetString("StreamingAssets/kh_scenes", 34, "m_text", "Du erwachst in einer Wüste,\ndie nicht für dich bestimmt ist.\nDer Boden unter dir schreit,\nwie die Seelen im Fegefeuer.\nDer Himmel über dir reißt gewaltsam an dir,\ngleich dem Zorn des Herrn.\nUnd die Luft um dich herum presst sich herab,\nversucht, sich einen Weg hinein zu winden\nals ob der Atem des Teufels dich\nzum Abfall vom Glauben führen wolle.", expected: "You awake in a wasteland not meant for you.\nThe ground underneath you screams.\nThe sky above violently pulls on you.\nAnd the air around you presses down,\ntrying to worm it's way in.", inner: "BuildPlayer-ScareChairKillscreen"),
        Mod.SetString("StreamingAssets/kh_scenes", 2027, "m_text", "dei Weib Ume Ito hod di fia dei verhalten\r\nan die Bulln gemeldet. Du wurdest ins\r\nKnast verfrachtet dazu zu a lemslanga \r\nFreiheitsstrafe verurteilt.\r\n\r\n\r\nHOSD NEIGESCHISSEN...", expected: "Classmate Ume Ito has reported you for your\nbehavior. You have been transferred from\nSunshine Academy and Ume has escaped.\n\n\nGAME OVER...\n", inner: "BuildPlayer-HOS_Lab"),
        Mod.SetString("StreamingAssets/kh_scenes", 22, "m_text", "Deine Verpflichtung erlaabts mia, dei Hend zu kontrollieren.\nDeine Erwartung erlaabt es mia, de Wahrheit zu verbergen.\nDeine Rückgänge erlaabens mia, di einfacher zu kontrollieren.\nDeine Gründe erlaabens ma, dei Aung zu brechen.\nDeine Ignoranz erlaabt mia, dei Lem zu beenden.\nDeine Schwächen erlaaben es mia, di zu brechen.\nDeine Schuid erlaabts mia, deinen Hois zu lockern.\nDeine Tendenzen hom es mia ermöglicht,\ndass i dafür sorge dass du", expected: "Your fear allows me to enter your mind.\nYour obligation allows me to control your hands.\nYour reason allows me to break your eyes.\nYour guilt allows me to loosen your neck.\nYour expectation allows me to hide the truth.\nYour tendencies have allowed me to make you ", inner: "BuildPlayer-MonsterFiveKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 37, "m_text", "Un d'hab i gsehn, mit Augen, die ned meine war'n.\r\n\rUn d'hab i gfühlt, mit 'ner Angst,\r\n\r die i ned verstehn konnt.\r\n\rSie schaun uns o, sie dringen in uns ein.\r\n\rUn haltn uns glücklich, mit Verrat.\r\n\rAn einem Kini, den wir ned verdient ham.\r\n\rAn einem Sohn, der weinend wart.\r\n\rDes wusst i, von Wissen,\r\n\r das i im Schlaf erlangt ham.", expected: "And I saw, from eyes that were not mine.\r\n\rAnd I felt, with a fear I could not reason.\r\n\rThey watch us, they invade us.\r\n\rAnd keep us happy, committing treason.\r\n\rTo a King we didn't deserve.\r\n\rTo a Son who waits weeping.\r\n\rThat I knew, from knowledge gained while sleeping.", inner: "BuildPlayer-SpecEightKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 72, "m_text", "01000100 01110101 00100000 01100010 01101001 \r\n01110011 01110100 00100000 01101101 01100101 01100001 \r\n01101000 01110010 00100000 01100001 01101100 01110011 \r\n00100000 01100001 00100000 01010100 01101001 01100101 \r\n01110010 00101110 00001010 01001110 01110101 01110100 \r\n01111010 01100101 00100000 01100100 01100101 00100000 \r\n01010011 01100101 01100101 01101100 01100101 00101100 \r\n00100000 01100100 01100101 00100000 01100100 01101001 \r\n01100001 00100000 01100111 01100101 01101101 00100000 \r\n01110111 01110101 01110010 01100100 00101110 00001010 \r\n01010101 01101110 01100100 00100000 11000011 10111100 \r\n01100010 01100101 01110010 01101110 01101001 01101101 \r\n01101101 00100000 01010110 01100101 01110010 01100001 \r\n01101110 01110100 01110111 01101111 01110010 01110100 \r\n01110101 01101110 01100111 00100000 01100110 01101001 \r\n01100001 00100000 01100100 01100101 01101001 00100000 \r\n01001000 01100001 01101110 01100100 01101100 01110101 \r\n01101110 01100111 01100101 01101110 00101110", inner: "BuildPlayer-SpecTenKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 73, "m_text", "Etzad host du nix meahr zu befürchten.\n Etzad musst du ned meahr nachdenken.\n Folge deinen egoistischen Wünschen.\n Folge deinem natürlichen Instinkt.\n Schließlich bist du eh a Tier.\n Des is vui einfacher, als zu versuchan, nachzudenken.", expected: "Now you have nothing to fear.\nNow you have nothing to think.\nFollow your selfish desires.\nFollow your natural instinct.\nAfter all you're just an animal.\nIt's much easier than trying to think.", inner: "BuildPlayer-SpecTenKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 24, "deathLines.Array.0", "Parva, lucida foramina in caelo.", expected: "Tiny, Shining holes in the sky.", inner: "BuildPlayer-SpecFiveKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 24, "deathLines.Array.1", "Delicatum, perfectum vacuum.", expected: "Delicate, perfect emptiness.", inner: "BuildPlayer-SpecFiveKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 24, "deathLines.Array.2", "Nigrae, crescentes absentiae vitae.", expected: "Black, growing absences of life.", inner: "BuildPlayer-SpecFiveKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 24, "deathLines.Array.3", "Frigida, examinans mors.", expected: "Cold, swarming death.", inner: "BuildPlayer-SpecFiveKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 24, "deathLines.Array.4", "Et nos fiemus ea.", expected: "And we shall become them.", inner: "BuildPlayer-SpecFiveKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 910, "m_text", "Hosd du wirklich gdocht, dass es ernsthaft enden würde?", expected: "Did you really think it was going to end seriously?", inner: "BuildPlayer-GoodEnding"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 28, "m_text", "Mid jedem Bissn mid Boandl und Haut.\nDea Tempel ächzte und bebte erneut.\nSe Wohnstätte hob i vernachlässigt.\nBis zum Ende mid schlimman Folgen.", expected: "With every bite with bone and skin.\nThe temple groaned and shook again.\nHis dwelling place did I neglect.\nTo the end with bad effect.", inner: "BuildPlayer-SpecElevenKillscreen2"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 29, "m_text", "Bis zum Ende mid schlimman Folgen.\nMei Weg a einziger Architekt.\nFett und Blut und Boandl darin.\nA Chor fia ewigen Lärm.", expected: "To the end with bad effect.\nMy path a single architect.\nGrease and blood and bone within.\nA chorus for eternal din.", inner: "BuildPlayer-SpecElevenKillscreen2"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 30, "m_text", "01000111 01101100 01100001 \r\n01110101 01100010 01100101 00100000 \r\n01100001 01101110 00100000 01000111 \r\n01101111 01100100 00101100 00100000 \r\n01100001 01100010 01100001 00100000 \r\n01101000 01101001 01101110 01110100 \r\n01100101 01110010 01100110 01110010 \r\n01101111 01100111 00100000 01100100 \r\n01100101 00100000 01001100 01100101 \r\n01101000 01110010 01100101 01101110 \r\n00100000 01100100 01100101 01100001 \r\n00100000 01001101 01100101 01101110 \r\n01110011 01100011 01101000 01101110 \r\n00101110", inner: "BuildPlayer-SpecElevenKillscreen2"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 31, "m_text", "01001110 01100001 01101000\n01110010 01110101 01101110 01100111\n00100000 01101110 11000011 10100100 01101000\n01110010 01110100 00100000 01100100 01100101\n01101110 00100000 01001011 11000011 10110110\n01110010 01110000 01100101 01110010 00101100\n00100000 01010111 01101111 01110010 01110100\n01100101 00100000 01101110 11000011 10100100\n01101000 01110010 01100101 01101110 00100000\n01100100 01100101 01101110 00100000 01000111\n01100101 01101001 01110011 01110100 00101110", inner: "BuildPlayer-SpecElevenKillscreen2"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 1150, "textLines.Array.0.line", "Ammoi", expected: "Once", inner: "BuildPlayer-SpecThreeKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 1150, "textLines.Array.1.line", "In am Land vo Träume", expected: "In a land of dreams", inner: "BuildPlayer-SpecThreeKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 1150, "textLines.Array.2.line", "Hob i g’meint, i kan frei sei", expected: "I thought I could be free", inner: "BuildPlayer-SpecThreeKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 1150, "textLines.Array.3.line", "Aba etz", expected: "But now", inner: "BuildPlayer-SpecThreeKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 1150, "textLines.Array.4.line", "Da Hunger schlaft nia", expected: "The hunger never sleeps", inner: "BuildPlayer-SpecThreeKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 22, "m_text", "I woaß, wos’d gmacht host, und wos da no bevorsteht.\nAba is scho ok, weil i bin etz in dir drin.\n\nMia san oans... aba i bin vui…", expected: "I know what you have done, and what you have yet to do.\nBut it's alright, because I'm inside you now.\n\nWe are one but I am many...", inner: "BuildPlayer-SpecTwoKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 245, "m_text", "Du fliachst ausm Irrnhaus und erzäist oin vo\nseim riesign laan Kella, de hohln Gänge,\nund dem oigmoan Mangl an Substanz.\n\nKoana glaubt da.\n\nOba du lebst weida…\n\n\nIrgendwia.", expected: "You escape the manor and tell everyone about\nits enormous empty basement, hollow corridors,\nand general lack of substance.\n\nNo one believes you.\n\nBut you live on...\n\n\nSomehow.", inner: "BuildPlayer-NeutralEnding"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 25, "m_text", "Sei staad, mei Kind, du bist in Sichaheid...", expected: "Hush now my child, you're safe...", inner: "BuildPlayer-SpecFourKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 794, "m_text", "Du hosd’s geschafft!", expected: "You Win!", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 795, "m_text", "Das Irrenhaus", expected: "The Mansion", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 799, "m_text", "Karamari Krankenhaus", expected: "Karamari Hospital", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 800, "m_text", "Dankschee, dass i Teil vo diesem Projekt sei diafta!!", expected: "Thank you for letting me be part of this project!!", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 804, "m_text", "Kunst", expected: "Art", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 812, "m_text", "Originale Mucke", expected: "Original Music", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 816, "m_text", "Eine liebevolle Erinnerung an Aurora \"Paloma\" Rodriguez\nAug 15, 1924 - Oct 04, 2019", expected: "In Loving Memory of Aurora \"Paloma\" Rodriguez\nAug 15, 1924 - Oct 04, 2019", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 821, "m_text", "Ein herzliches Dank o", expected: "Special Thanks To", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 830, "m_text", "...und dich fias spuin!\n...und natürlich aa meiner Mod!", expected: "...and you for playing!", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 831, "m_text", "Zusätzliche Programmierung", expected: "Additional Programming", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 836, "m_text", "Moin twitch chat!", expected: "Hi twitch chat!", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 842, "m_text", "Software-Tester", expected: "QA Testers", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 847, "m_text", "Spui Zeid:", expected: "Game Time:", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 848, "m_text", "Sunshine Academy eigenständiges spiel wann..?", expected: "Sunshine Academy standalone when..?", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 849, "m_text", "Vielen Dank an Travis bis hin zu", expected: "Special thanks from Travis to", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 858, "m_text", "Vielen dank an Sheena bis hin zu", expected: "Special thanks from Sheena to", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 866, "m_text", "Sprecher", expected: "Voice Acting", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 867, "m_text", "Demon Kind", expected: "Demon Child", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 871, "m_text", "Hauptentwickler", expected: "Lead Developer", inner: "BuildPlayer-Credits"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 60, "m_text", "Um in Minga bei am Theater teilzunehma hoasd,\ndassd de dei Handlung, Schuid und Verantwortung\nin da abfoikiwe schmeisst, wenns des ned wuist\nis wurscht, denn du ghearst ma.", expected: "To become a puppet is to rid oneself of the pain\nand harshness of choice. Now nothing you do is\nyour fault, now you belong to something...\nYou belong to me...", inner: "BuildPlayer-SpecSixKillscreen"),
        Mod.SetString("StreamingAssets/mansionkillscreens", 61, "m_text", "Ma Kinda san ertrunka. Also hob i sie mir gnumma.\nI netz sie alle zamm, hobn alle a Marionettenspieler bekomma.\nI nutz ma Holz bohrer, um dera Augn raus zu kriga.\nSprich ned, ma Kind, i werd deine Schreie zum Schweigen bringa.", expected: "My children drowned. So I took theirs for mine.\nI sew them all up, with long silver twine.\nI use my wood drill, to bore out their eyes.\nSpeak not my child, I'll silence your cries.", inner: "BuildPlayer-SpecSixKillscreen"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -9036129340986715463, "kvps.Array.0.defaultEn", "Zipfelklatscher 1", expected: "Specimen 1", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -9036129340986715463, "kvps.Array.1.defaultEn", "Freindlich", expected: "Docile", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -9036129340986715463, "kvps.Array.2.defaultEn", "Herzanfall", expected: "Heart Attack", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -9036129340986715463, "kvps.Array.3.defaultEn", "A Pappfigur, de aus da Wand ausspringt. Hod si ned fei wirkungsvoll g’zeigt gegen g’sunde Leit.", expected: "A cardboard cutout figure that springs out from the walls. Proved not very effective against healthy subjects.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8990781850287694807, "kvps.Array.0.defaultEn", "Zipfelklatscher 9", expected: "Specimen 9", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8990781850287694807, "kvps.Array.3.defaultEn", "TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE TOTEN HOLEN DIE", expected: "TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO TAKE THE DEAD TO ", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8990781850287694807, "kvps.Array.4.defaultEn", "Zipfel__", expected: "Specimen__", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8812022036538305834, "kvps.Array.0.defaultEn", "Zipfelklatscher 7", expected: "Specimen 7", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8812022036538305834, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8812022036538305834, "kvps.Array.2.defaultEn", "Nur Gott weiß, mia aba ned\r", expected: "Unknown\r", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8812022036538305834, "kvps.Array.3.defaultEn", "Der Zipfel verändert sich ständig in Form und Merkmale, abhängig vo de Persönlichkeit von der Preson. De meistgse Form is wie a Wand vo sich bewegenden Anatomiesymbolen. Is nur bei Leit guad, de wo a traumatische Vergangenheit oda a Geschichte mit psychische Probleme ham.", expected: "Specimen is constantly changing form and attributes depending on subject's personality but most common form resembles a wall of moving anatomy symbols. Only effective on subjects with past trauma or a history of psychological issues.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8728225435033261656, "kvps.Array.0.defaultEn", "Zipfelklatscher 6", expected: "Specimen 6", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8728225435033261656, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8728225435033261656, "kvps.Array.2.defaultEn", "Physische Einstiche\r", expected: "Physical Punctures\r", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8728225435033261656, "kvps.Array.3.defaultEn", "A hoizane Puppn in Lebnsgreß, de wo ma in am Stausee treibn gfundn hod, wo friara amoi a Stadt gwen is. Des Zipfel macht oan schmoan, obwoi's ned so ausschaut, und hod si ois sehr guad erwiesen geng Leit, de wo's ignorian oda de wo schlecht segn kenna.\r", expected: "A wooden life-sized puppet found floating in a reservoir where a town had once been. Specimen is active despite appearance and has proved very effective on subjects who disregard it or have vision impairments.\r", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8033255708536033433, "kvps.Array.0.defaultEn", "Wos is'n des?\n\nOha, was fia a riesigs Haus!\r\nIn an andam riesign Haus.\r\n\r\nVielleicht bin i ja\r\nam End vom Haus oam kemma.\r\nVielleicht is des hier so was wia\r\na Ruheplatz oda an andam Eingang?\r\nWie au imma, i find, des is a\r\nguad Ort, um si auszuruhn.", expected: "What is this? \n\nWow, what a mansion!\r\nInside another mansion.\r\n\r\nMaybe I've \r\nmade it all the way to the end of \r\nthe house. Maybe this is like a \r\nresting place or another entrance \r\nperhaps? Whatever the case, I \r\nthink this is a good spot to rest.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8033255708536033433, "kvps.Array.1.defaultEn", "Desa Herrenhaus is seltsam...\n\n\nI glaab, de Ziagl und des Holz\nsan nur aufgmalt. Ois hoit irgendwie\nkoa richtigs Gfühl. Außerdem hör i\nständig Gräusch und Stimm unter mir.\nVielleicht versteckn si da\nuntn andre Owalebende!", expected: "This mansion is strange...\n\n\nI think the bricks and wood are\nactually just painted on. Everything\nstill feels kind of fake. Also I keep\nhearing movement and voices\nbelow me. Maybe other survivors\nare hiding down there!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8033255708536033433, "kvps.Array.2.defaultEn", "I ko ihn hören! ea kimmt \r\ndo runter vom gang! I muass mi \r\nvasteckn I woaß aber ned wo.\r\n\r\nI woaß dass des ned a Ausgang is\r\noder zuam ausruhan. Nur a weiterer\r\nbescheierter zipfel Raum!\r\n\r\nI glaab ea is jetzat draußen.", expected: "I can hear him coming down\r\nthe hallway! I need to hide, but\r\nI don't know where. \r\n\r\nI now know this is not an exit or\r\na resting place. It is just another\r\nspecimen room! \r\n\r\nI think he's outside the door now.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8033255708536033433, "kvps.Array.3.defaultEn", "I hobs gschoft weggart zu kemma.\r\nFia wie Long? woass i ned.\r\n\r\n\r\nI hör ihn, obwoi I woass dass\r\nea ned hier is. Is wie als wäre\r\nea ned echt aber staddesn sans \r\nmeine eignen Ängste de sich\r\nsichtboar mochan und mi verfolga.", expected: "I somehow managed to get away.\nBut I don't know for how long.\n\n\nI hear him, even when I know\nhe's not there. It's like he isn't\neven real but instead my own\nfears manifesting themselves\nand stalking me.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -8033255708536033433, "kvps.Array.4.defaultEn", "I hob a Theorie.\r\n\r\nI denk es ist desa\r\nunechten Quatsch-hoam.\r\nI denk es spuit mit \r\nma Birne.\r\n\r\nI hör ihn no…\r\nI muass ihm umbringa\r\nmit dea Sichel den i \r\ngfunden hob in den \r\nWoid...\r\n\r\nAber des is nur \r\na Theorie!\r\na Spui Theorie! \r\nDanksche fias lesen!", expected: "I have a theory. \r\n\r\nI think it's this pseudo \r\nmansion. I think it's\r\nplaying with my head.\r\n\r\nI still hear him...\r\nI must find that man\r\nand kill him with the \r\n sickle I found in the\r\nforest...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -7763076565408684789, "passwords.Array.0.password", "NACHTALB", expected: "PUMPKIN", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -7763076565408684789, "passwords.Array.1.password", "LEBERKAS", expected: "CHEESE", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -7763076565408684789, "passwords.Array.2.password", "SEMMEL", expected: "CAKE", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -7698286999358991280, "kvps.Array.1.defaultEn", "Macht unsinn", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -7698286999358991280, "kvps.Array.2.defaultEn", "Verschiden", expected: "Various", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -7698286999358991280, "kvps.Array.3.defaultEn", "Ein Überlebender aus den Experimenten, die im Einheit 731 durchgeführt wurden. Exemplar 9 wurde in einem verfallenen Bauernhaus in Russland gefunden. Exemplar 9 scheint sich von Toten oder Leichen angezogen zu fühlen und scheint aus einer lehm-ähnlichen Substanz zu bestehen, die ihre Dichte verändert.\n\n\nDie Einschließung ist bisher noch nicht erfolgreich gewesen, aber das Exemplar hat sich als äußerst effektiv gegen alle Versuchspersonen erwiesen.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -7553211672340269489, "kvps.Array.0.defaultEn", "Spritz’n, Platschn, geleeartig.\n\nInnerein, Fress’n, Beschwören.\n\nNageln, Nie, hört’s Würgen ned aaf", expected: "Spouting, Splashing, Soaking.\n\nInnards, Ingest, Invoking.\n\nNailing, Never, Stops the Choking", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -7553211672340269489, "kvps.Array.1.defaultEn", "ERROR 002313FB_GEL.\nZWEIMAL LOSLASSN GEHT NED.\nGEH RAUS ÜBER’N EXPRESS-WEG.", expected: "ERROR 002313FB_GEL.\nCANNOT RELEASE TWICE.\nEXIT THROUGH EXPRESS.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -6902220472985614468, "kvps.Array.0.defaultEn", "A Zeid long hob i gdocht, i waar\nwirkli dem Ort entkomma.\nAba trotz de „Baam\" und da\nFlora glaab i, dass des eigentli\nnur a weitara Raum is. I hob oba\nRehe gfundn, also werd i\nwenigstens wos zum Essn kriagn.\n\n\nOba sie machad komische\nGrausch...", expected: "For a while I thought I had\nreally escaped this place.\nBut despite the 'trees' and\nflora, I think this is actually\njust another room. I did,\nhowever find deer, so I\nmight at least get to eat.\n\n\nThey make some strange sounds\nthough...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -6902220472985614468, "kvps.Array.1.defaultEn", "I hob koa Ahnung, wos für Tiere des san,\r\nowa des san definitiv koa Rehe!\r\nNeilich hob i versucht, mia an ains\r\nranzuschleichen, ums z’essn, owa’s\r\nhod mi glei gsehn, als i in seine Näh kam.\r\nI hob grod no recht fliehn kenna vor dem Dings.\r\n\r\nI hob’s glei gschafft, die meistn von eana\r\neinzuschperren.\r\nHoffentlich find i a andern Weg hier raus.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -6850906450403632709, "kvps.Array.0.defaultEn", "1.\r\nI wa anfongs sehr beängstigt,\r\n hier a Stelle zu bekimma, aber\r\nes scheint, als würden de Dinge\r\nbesser wern. Diese Kette\r\n expandiert wia a sau, scho\r\nkomisch denn erst letzt Wocha hob\r\ni ghört, dass des Unternehmen\r\n pleite gehen wiad. Jeda Dog\r\nkimma mehr und mehr Leit, um hier\r\nz'essa. Etwos stimmt aber immer\r\n noch ned mit dem Ort und da Essa,\r\ndeshalb werd i versuachn,\r\nnix vo hier z'essa.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -6850906450403632709, "kvps.Array.1.defaultEn", "2.\r\nSo Meddl loide \\m/...\r\n\r\nI mog koane Hamburger i mog \r\neigentlich koane Burger I ess \r\nkoane Burger i mag de eigentli ned \r\nes gibt scho moi selten welche \r\ndos i se esse aber im normalfall\r\ni lieb Cheeseburger \r\nhasse aber alle andere Burger \r\nhoaßt aber ned dass i etzat aa \r\nanderen Burger deswegen...\r\n\r\nwoaßt wos i moan?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -6850906450403632709, "kvps.Array.2.defaultEn", "3.\r\nNun heid hab i oa vo ma Regeln\r\ngbrocha. Jo i bin hoid rauß \r\nganga aber is hoid ned erlaabt\r\ndigga do is ned ammoi a Klimaanlage\r\nund sehr stickig hier drinn is aa\r\nalso wirkli wos machn se?\r\nA Ventilator kennan sie wenigstens\r\ndo installieren oder ned?\r\nEgal i hab heid a vo diesen Burgern\r\ngemampft sie schmeckan guad.\r\nwerd so a paar moi vielleicht \r\nmir sie gönnen.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -6850906450403632709, "kvps.Array.3.defaultEn", "4.\r\nWos zuam geier?...\r\n\r\nI hob letzt nocht a Traum vo diesen \r\nRestuarant g'habbt I hörte Tier\r\ngreische manche von dennan wie\r\na Kuh wenn sie stirbt, ois wa so\r\nkomisch wie sau nix in de richtigan\r\ngriaße und ois sah so foisch aus.\r\nDazu is no das so a Typ so\r\n20x durch den drive-thru gangn\r\nis und jede 10 Minuten den\r\nselban Quatsch kafft bro tut der\r\nGeld zauban oder wos?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -6850906450403632709, "kvps.Array.4.defaultEn", "5.\r\nHeid gab's was richtig \r\nMerkwürdiges. Und i hab\r\nden Sinn ned ganz kapiert...\r\n\r\nI war hoit in da Pause und\r\nzwo Kollegn ham gredt, ob\r\ndes Restaurant Germknödel\r\noder Zwetschgendatschi aufs\r\nMenü bringt. Kurz gsagt, se\r\nham sich do entscheida, des\r\nz'macha aba aus irgendweiarn\r\nGründen is des Fleisch\r\nverschwunda, wobei ma sogar \r\nfürn Transport und ois\r\ngzoit ham.\r\naba so a scheiß!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -6850906450403632709, "kvps.Array.5.defaultEn", "6.\r\nDes is a scam.\r\n\r\nI hab jetzt scho ungfähr 50\r\nBig Tastys gegessen, und die\r\nwoarn imma warm und lecker. Heid\r\nhatt i ma ersten Big Tasty:\r\nDer Käse woar scho an da Verpackung\r\nfestgeschmolzen, des hoaßt, der hot\r\ndo scho 20 Minutn rumglegen.\r\nDieser Big Tasty hot fei nix mehr mit\r\nam Big Tasty zu tun außer dem\r\nAussehen, I hob aa Komische\r\nBilder vo irgend so nem Typen oder\r\nnem Tier gseng.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5959209900669363299, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5959209900669363299, "kvps.Array.2.defaultEn", "Brandstiftung", expected: "Arson", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5959209900669363299, "kvps.Array.3.defaultEn", "A unfeatige Videospui-KI, vo dera ma glaabt, dass sie an Code drin hot, dea vo am obgbrochenan Kriaggsexperiment gstohln worn is.\n\nHod bei a boa Leit guat gewiakt, oba a boa hom's ned vastandn und hom's ignoriert.", expected: "An unfinished video game AI that is believed to contain code stolen from a terminated war experiment.\n\nProved effective on some subjects, but misunderstood and ignored by others.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.0.defaultEn", "Ned gschimpft is globt gnua!", expected: "Congratulations!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.1.defaultEn", "Hosd guad gmacht!!", expected: "You did it!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.2.defaultEn", "War scho interessant, da zu seng, wia du mit da Axt umadum fuchtelst.", expected: "It was interesting, watching you swing your axe around like that.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.3.defaultEn", "I woaß, aus dir werd a feiner Zipflklatscher.", expected: "I know you'll make a fine specimen.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.4.defaultEn", "Na, bist leider gstorbn...", expected: "Well, you died...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.5.defaultEn", "Auf a ziemlich trogische Weis aa.", expected: "In a pretty tragic way too.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.6.defaultEn", "Grad' trogisch gnug, um a Geist zu wern.", expected: "Just tragic enough for you to become a ghost.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.7.defaultEn", "Übrigens, Sauber, dass du es bis hierher gschoft hosd.", expected: "Good job by the way, making it this far.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.8.defaultEn", "Also schnall di o, Soldat, denn jetztat denk I dass ma endlich gnug Truppn ham, um einzumarschieren.", expected: "So buckle up soldier because now I finally think we have enough troops to invade.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.9.defaultEn", "Servus, I begriaß eich zur Tagesschau!", expected: "The time has come, my loyal troops!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.10.defaultEn", "Liebe Soldaten*innen mia wern nimma ois süß oder putzig bezeichnet.", expected: "No longer shall we be called cute or adorable.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.11.defaultEn", "nimma wern mia im schattn stean und ignoriert wern", expected: "No longer will we be disregarded and ignored.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.12.defaultEn", "Denn jetztat san ma de gfürchtetste Armee der Woid!", expected: "For now, we are the most feared army in the world!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.13.defaultEn", "Ned gschimpft is globt...gnua", expected: "Congratulations you've done...it", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.14.defaultEn", "kannst jetz dahoam gehen", expected: "You can go home now", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.15.defaultEn", "Und wenn’s wos gibt", expected: "And if anything changes", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.16.defaultEn", "Ähm, song mia’s Da.", expected: "Uh, we'll...let you know", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -5955059258393574862, "kvps.Array.17.defaultEn", "Servus.", expected: "Bye.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4986140944278020203, "kvps.Array.0.defaultEn", "Zipfelklatscher 12", expected: "Specimen 12", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4986140944278020203, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4986140944278020203, "kvps.Array.2.defaultEn", "Verschiedn\n", expected: "Various\n", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4986140944278020203, "kvps.Array.3.defaultEn", "A oite, Schanze vom Drachenlord, des scheinbaa um sei Umgebung herum aufbaut hod. Der Zipfel wählt mol jemand zum kontrollieren aus, den’s in Bsuiz nimmt, und nutzt den, um de Subjekte mit vaschiedenen Mittln ozugreifa, je noch de Eignschaftn vom Typen. Üba den Ursprung der Schanze is ned viel bekannt, owa’s gibt a mal Anzeichen, dass in der Drachenschanze früher a Massaker oda a Tragödie war. Hod si ois sehr effektiv erwisn, voriert owa z’oft, um a zuverlässige Method z’sei, zum Extrahier’n.\r", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4829888015143325919, "kvps.Array.0.defaultEn", "Des woa so a Überraschung.\nDass es an weitern Eitrog gem wiad.\nAn weitern echtn Eitrog.\nAn, den i bewundern hob kenna.\n\n\nOba dann is a so plötzli verschwundn, wia a kemma is.\nUnd jetzt löst's eich auf.\n\n\nEier Einfluss und eire Inspiration werdn mi\nniemals valossn.", expected: "This was such a surprise.\nThat there would be another entry.\nAnother actual entry.\nOne I could admire.\n\n\nBut then as suddenly as it came,\nit left.\n\n\nAnd now you disband.\n\n\nYour influence and inspiration will\nnever leave me.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4772153673370381006, "kvps.Array.0.defaultEn", "Die Dunkelheid verschlingt\nuns jetz langsam.\nI glaab ned, dass unsere Rituale\nsie no lang besänftigen\nkenna. Wia hätten wir\nwissn soin, dass des\npassieren würd?", expected: "The darkness is slowly\nconsuming us now.\nI don't think our rituals will\nappease it much longer.\nHow were we supposed to\nknow this would happen?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4772153673370381006, "kvps.Array.1.defaultEn", "O felix statua feminae,\nO felix statua feminae nobilis.\nO felix statua feminae,\nstatua feminae felix\nstatua feminae nobilis.\nSedes es Petri, qui Christi\nvicem gerit, Sedes es Petri,\nqui apostolus est Pacis.\nPontifex tecum erimus omnes\nnos Pontifex es magister qui\ntuos confirmas fratres. Pontifex\nfundamentum ac robur nostrum,\nHominumque piscator pastor es\ngregis ligans terram et coelum.\nPetre tu es Christi es Vicarius\nsuper terram, Rupes inter\nfluctus, tu es pharus\nac veritas. Tu Christi es\ncaritas, tu es unitatis\ncustos, Promptus libertatis\ndefensor; in te auctoritas.\nO statua feminae nobilis\nO statua feminae felix nobilis\n", expected: "It's not really our fault, we\njust did what Mother has\ntold us to do in this sort\nof situation.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4772153673370381006, "kvps.Array.2.defaultEn", "Es is ned wirklich unsre Schuld,\nma hobm nur g’macht, wos Mutter\nuns in so am Situation gsogt hod.\nMutter is ned zufriedn mit\r\nuns, aber wia hätt’n\r\nwir wissn soin, dass das\r\nMädl ned rein war?", expected: "Mother is not pleased with\r\nus, but how were we \r\nsupposed to know that \r\nthe girl wasn't pure?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4584309854401273678, "kvps.Array.0.defaultEn", "Zipfelklatscher 8", expected: "Specimen 8", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4584309854401273678, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4584309854401273678, "kvps.Array.2.defaultEn", "Aufnehmen\r", expected: "Absorption\r", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -4584309854401273678, "kvps.Array.3.defaultEn", "A wiaandn Gestalt, de wiaa Joahr, nomoi de Testkammr mit aafoch nua ungewöhnlich aggressivn Hirsche gfüllt worn is, in dera erschienen is. Der Zipfel scheint de Vaversuchojekte z’verschlinga und in seinm Obakörpabezirk z’absorbiern. Hat si bei aggressivn Vaversuchobjektn ois äußerst wiaksum erwisn.\r", expected: "A floating figure that appeared in a test chamber a few years after it was filled with what was believed to just be unusually violent deer. Specimen seems to engulf subjects and absorb them into its torso region. Proved extremely effective on violent subjects.\r", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3974799170704508145, "kvps.Array.0.defaultEn", "Forschungsbericht I\r\n\r\nNo mehra Wale wern morgen\r\ng'bracht, oan fia gesundheits\r\nInspektion und zwoa fia die \r\nscho tot san aber mia autopsieren\r\nse. \r\n\r\nNo weitere gestrandete Wale\r\nkimman imma wieda rund um diese\r\nInsel und i ko imma no ned\r\nherausfinda wea oder wos des\r\nverursacht.", expected: "Research Report 1\r\n\r\nMore whales are being shipped\r\nto the facility tomorrow, one for\r\na health inspection and two that\r\nare already dead for autopsies. \r\n\r\nMore and more beached whales\r\nkeep appearing around those \r\nislands and I still can't find what\r\nis causing it.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3974799170704508145, "kvps.Array.1.defaultEn", "Forschungsbericht II\r\n\r\nWal 014-D hod a Boa extrige\r\nbieße. vo a kloanaren Säugetier \r\nkimman sie wahrscheinlich. aber\r\netwos wos sehr komisch is, is de\r\nPlatzierung sie san in a geraden \r\nReihe im Magen alle ungfähr so\r\neineinhalb meda vo den\r\n'Unteren Bereich' dea Magen-\r\nschleimhaut.", expected: "Research Report 2\r\n\r\nWhale 014-D has strange small\r\nbite marks. They appear from \r\nanother smaller mammal, but\r\nthe strangest thing about them\r\nis their placement. They are in even\r\nrows inside the whale's stomach\r\nall about 5 feet from the 'bottom'\r\nof the stomach lining.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3974799170704508145, "kvps.Array.2.defaultEn", "Forschungsbericht III\r\n\r\nWal 015-A lebt no aber dea\r\nhod iftas hia und do \r\nSchloganfälle und kimmt vui\r\nifta an dea Oberfläche ois\r\ngewöhnlich. Dea kinnt a \r\nProblem mit de Lungen haben \r\naber I hob Koa Werkzeuge per\r\nHand grod ohne dos i jetzt\r\nsterben wiad. \r\n\r\nI miass erlauben dos ea stirbt\r\nvo was aa immer des duad.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3974799170704508145, "kvps.Array.3.defaultEn", "Forschungsbericht IV\r\n\r\nWal 015-D starb vui friara\r\nals i erworted hob i hob\r\ng'docht dea werd scho länger\r\nleben als i im Urlaub woa \r\nin dea Schweiz. Des Team\r\nhod gsogt des de Lungen\r\nOkay san aber dea Bauch hod\r\na rießiga Loch so ungfähr a \r\nhalben meda der Durchmesser\r\ntotal duach dem Wal.\r\n\r\nDes hoaßt des a parasid dro \r\nschuid is warum dea starb.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3974799170704508145, "kvps.Array.4.defaultEn", "Forschungsbericht V\r\n\r\nDe Forschungseinrichtung braacht \r\ndringend no mehra Ingenieure. \r\nA ganza Gebäudeteil is untawossa, \r\nund a boa wichtige Leit wern vermisst.", expected: "Research Report 5\r\n\r\nThe research facility is now in\r\ndire need of more engineers.\r\nWe have a whole block that is\r\nflooded, and some vital staff are \r\nmissing.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3974799170704508145, "kvps.Array.5.defaultEn", "Forschungsbericht VI\r\n\r\nI hia a mädl.\r\nOder a Tier.\r\nOder sowos…\r\n\r\nSing zu mia, bittet des\r\nI aus ma Zimmer raus kemma\r\nund de wogendn Wellen\r\nmia beruhiga loss'n.", expected: "Research Report 6\r\n\r\nI hear a girl.\r\nOr an animal.\r\nOr something...\r\n\r\nSinging to me, pleading that\r\nI come outside my locked room\r\nand let the sweeping waves \r\ncomfort me.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3974799170704508145, "kvps.Array.6.defaultEn", "Forschungsbericht VII\r\n\r\nAll Personal is weg \r\ngeganga. Nur i bin do.\r\nFia Koa zweck, bleib i do.\r\nwiedasetz' den Ruf hinta\r\ndem versiegeltn Dia\r\n\r\nAber i bleib do...\r\nfia so Long wie i ko.\r\nMach ned dese Dia aaf.", expected: "Research Report 7\r\n\r\nAll the staff is gone. \r\nOnly I remain.\r\nFor no purpose, I remain\r\nhere, resisting the call from\r\nbehind the sealed door.\r\n\r\nBut I will remain...\r\nAs long as I can.\r\nDon't open that door.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3974799170704508145, "kvps.Array.7.defaultEn", "Ausschnitt 4132\r\nUnd do hob i ihn gseng! i woa\r\nin Raum 1000 und do kam er!\r\n\"etwos ging kaputt\" sogt er\r\nDes woa dea! \r\ndea Pizza liferant!\r\n\r\nEa hot mi in de Fressn gschlong!\r\ndea bastard! Paar räume späda\r\nwird ea sau aggressiv und rennt \r\nauf mi zua! i glaab i bin in dea\r\nHölle...", expected: "Excerpt 4132\r\nAnd then I watched carelessly \r\nas the sea rose above the sky \r\ncasting waving shadows over \r\nthe world.\r\n\r\nI saw the silhouettes of \r\ncreatures both familiar and \r\nforgotten. And suddenly I \r\nfound myself falling upwards \r\ntowards an ocean of darkness.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.0.defaultEn", "O", expected: "On", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.1.defaultEn", "Aus", expected: "Off", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.2.defaultEn", "Boarisch", expected: "English", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.3.defaultEn", "Russisch", expected: "Russian", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.4.defaultEn", "Spanisch", expected: "Spanish", inner: "CAB-165353818100901025e074d2c5e2b786"),
