        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.6.defaultEn", "Japanisch", expected: "Japanese", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.7.defaultEn", "Polnisch", expected: "Polish", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.11.defaultEn", "Generell", expected: "General", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.12.defaultEn", "Grafik", expected: "Graphics", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.13.defaultEn", "Eingabe", expected: "Input", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.14.defaultEn", "Französisch", expected: "French", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.15.defaultEn", "Niederländisch", expected: "Dutch", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -3394874571739135542, "kvps.Array.17.defaultEn", "Im Spui", expected: "In Game", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -2360946047096368514, "kvps.Array.0.defaultEn", "Zipfelklatscher 4", expected: "Specimen 4", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -2360946047096368514, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -2360946047096368514, "kvps.Array.2.defaultEn", "Fresserei\r", expected: "Consumption\r", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -2360946047096368514, "kvps.Array.3.defaultEn", "A Japaner-zipfel-Geist ausm 14. Jahrhundert, den’s ei’fangt ham und jetz do eing’sperrt ham. De Versuach ham no ned rausgfundn, woher der eig’ntlich kimmt, aber ois, wos relevant is, ham’s ins Test-Kammerl neiglegt. Hod si als wirkungsvoll erwiesen, aber ned vui besser ois de voherig’n Zipfelklatscher.", expected: "A 14th century spirit that was contained and relocated here. Tests have yet to reveal origins, but all relevant information has been placed into testing chamber. Proved effective, but not greatly more than previous specimens.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -1497641068856586445, "kvps.Array.2.defaultEn", "Idioma bávaro", expected: "Inglés", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -1125066380755749764, "kvps.Array.0.defaultEn", "Matsuri is heid ned zum\nUnterricht kemma, I hoff sie\nis guad hoam kemma.", expected: "Matsuri never came to\nclass today, I hope she\nmade it home ok.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", -1125066380755749764, "kvps.Array.1.defaultEn", "Könnt’s wirklich wahr sei?\nI hab gdocht, de Märchen\nvom Geist, der Kinda frisst\nwos si nochm Unterricht einschleim\ndienen nur dazu uns\ndavo obzuhalten, ungehorsam z’sei.\nAber Matsuri wird\nimmer no vermisst. wos is a des?", expected: "Could it really be true?\nI thought the fairy tales\nabout the ghost that eats\nchildren who sneak in after\nclass was just to keep us\nfrom disobeying. But\nMatsuri is still missing.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1138179252722999490, "kvps.Array.0.defaultEn", "I hob so paar Tiere gseng die i\r\neigentli ned zuvor gseng hob.\r\n\r\nSo a Wolpertinger den ma eigentli \r\nnur so kinnt aber anscheinend gibts \r\nden in echt aa... \r\nvalier i den verstand oder ned?", expected: "This place is finally starting to \r\naffect me.\r\n\r\nI've seen enough horror movies to \r\nknow how to survive a simple ghost \r\nor two, but these monsters keep \r\ngetting faster and stranger.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1138179252722999490, "kvps.Array.1.defaultEn", "Als i aaf de Alpen war hab i ihn doch\r\ngseng er hod mi do hi gbracht... \r\n\r\nI denk Gott wui dos i wos rausfind \r\nals 'Hauptfigur' werd i warscheinlich \r\nIrgendwelche zauberein veranstallten.\r\n\r\n'Pack do ne unbekannte horror\r\nanspielung einne de konna versteht \r\nund denkt sie sein Anleitungn'", expected: "In order to survive this house I need\r\nto keep writing notes. \r\n\r\nI must do everything a central \r\nprotagonist would and hope this is \r\none of those stories.\r\n\r\n'Insert Obscure horror reference that\r\nno one gets and misinterprets as \r\ninstructions somehow'", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1138179252722999490, "kvps.Array.2.defaultEn", "I hob des Fabelwesa no ned gfunda aber\r\nI bin wahrscheinlich jetzat, \r\nder Protagonist wäre super... \r\n\r\nI hoff i bin koa unnötiger neben \r\ncharakter der nur do is und quatsch \r\nlabbert.\r\n\r\nI hob aa an komischn Computer gfunda\r\ndes so Beschreibungen vo de zipfeln gibt. \r\ndie schaung alle total scheisse aus.\r\naa schmincke tuads aa ned helfa.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1138179252722999490, "kvps.Array.3.defaultEn", "I glaab wie \"effektiv\" sie san\r\nhod aa wos damit zu tua mit de\r\nSeelen vo dena Lei'd sie töten\r\n\r\nNun i bin no fit wie a Turnschuh,\r\nI denk ma Reise hod grad erst \r\nbegunna und es erwartet mi a haffn\r\nzeig.\r\n\r\nI frog mi wie der Antagonist\r\nausschaung tat.\r\n\r\nI hoff der oder die is goidig.", expected: "I think the 'effectiveness' of \r\nthe Specimens is also somehow related \r\nto the souls of the people they \r\nkill somehow...\r\n\r\nAnyway I'm still alive and strong, \r\nbut I feel like the inmost cave \r\nof my journey lies ahead. \r\n\r\nI wonder what the antagonist \r\nwill look like. \r\n\r\nI hope they're cute.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1138179252722999490, "kvps.Array.4.defaultEn", "Mia is grad klar gworn, dass i nie a\r\nMentorfigur, a Prüfung oder a \r\nSzene hatte, in der i vo dahoam \r\nweggeganga bi und vielleicht war das mit\r\ndem Fabelwesen a streich.\r\n\r\nDes hoaßt, dass diese Geschicht' ned den\r\nArchetypen folgt, die mi zu a\r\ntraditionelln Helden mochan würdn.\r\n\r\nDes hoaßt, dass i getötet wern ko.\r\n\r\nNun, war es fia kurze Zeid schee.", expected: "I just realized that I never had a \r\nmentor figure, trial, or leaving \r\nhome scene. \r\n\r\nThat means this story isn't following \r\nthe  archetypes to make me a \r\ntraditional hero. \r\n\r\nWhich means I can be killed off.\r\n\r\nWell it was nice for a little \r\nwhile at least.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1517747135703627929, "kvps.Array.0.defaultEn", "DER_MATRAZENMANN", expected: "THE_MATTRESS_MAN", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1517747135703627929, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1517747135703627929, "kvps.Array.2.defaultEn", "Schrein", expected: "Screaming", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1517747135703627929, "kvps.Array.3.defaultEn", "A seltsame Kreatur aus Haut, die über a Bettrahmen gespannt is. Der Zipfel is im Grunde gnumma nur a unsichtbarer schneller Zombie mit einem Schmerzauslöser und a flochn Texturbox, die daran angeschweißt is.\n\nHod si als sehr effektiv erwiesen, um Probanden zum Schrein und Davonalafn z'bringa.", expected: "A strange creature made of skin stretched over a bed frame. The specimen is basically just an invisible fast zombie with a hurt trigger and a flat texture box welded to it.\n\nProved very effective at making subjects scream and run away.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.0.defaultEn", "des groaße Haus", expected: "The Mansion", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.1.defaultEn", "A frisch hergricht’s Spukhaus, genau wia’s ganz am Anfang aa war!", expected: "A renovated version of the original Jump Scare Mansion!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.2.defaultEn", "Baue-dein-eigenen Irrenhaus", expected: "Build-your-own mansion", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.3.defaultEn", "Kimmt a moi!", expected: "Coming Eventually!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.4.defaultEn", "Endlosmodus", expected: "Endless Mode", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.5.defaultEn", "Karamari Krankenhaus", expected: "Karamari Hospital", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.6.defaultEn", "Kimmt Boid!", expected: "Coming Soon!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.7.defaultEn", "Entschliassl de Geheimnisse vo dera gspinstigen verlassenen Kranknhaus", expected: "Unlock the secrets of this strange abandoned hospital", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.8.defaultEn", "Verschmiz mit’m Ewigen!", expected: "Embrace infinity", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.9.defaultEn", "Spookys Katholische Familie", expected: "Spooky's Dollhouse", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.10.defaultEn", "Beend di Gschicht", expected: "Finish the story", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 1583011828540539292, "kvps.Array.11.defaultEn", "Es is no net vorbei", expected: "It's not over yet", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2388623746029334750, "kvps.Array.0.defaultEn", "Zipfelklatscher 10", expected: "Specimen 10", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2388623746029334750, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2388623746029334750, "kvps.Array.2.defaultEn", "Parasitäre Infektionen", expected: "Parasitic Infections", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2388623746029334750, "kvps.Array.3.defaultEn", "A Wesn, des sei Form wandlt und umanhafft a Fremdling is, obwoa des ned offiziell bewiesn woa. Hod si ois extrem guad erwiesen geng de meistn Probanden, is aber zu schwierich zum eigschnian, so dass's gfoahlich is. Der Zipfel is aus sei Gfängnis ausbrochn, weil's oft Stromprobleme gab.\n", expected: "A form changing creature that is believed to be an extraterrestrial, though it was not officially proven. Proved very effective on most subjects, but deemed too difficult to contain. The specimen broke out of its containment area due to frequent electrical malfunctions.\n", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2699867187143063811, "kvps.Array.0.defaultEn", "Zerscht sah da Ort niedlich aus,\r\naba i bin scho seid Tagen do …\r\nI fühl mi jetzt rechd ausgetrocknet, und\r\nI hob ständig des Gfühl, dass i vo\r\nwos beobocht wern.\r\n\r\nDes is überhaupt ned romantisch ...", expected: "At first this place just seemed cute,\r\nbut I've been here for days now…\r\nI'm feeling quite parched now, and\r\nI keep getting this feeling like I am\r\nbeing watched by something.\r\n\r\nThis is not romantic at all...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2699867187143063811, "kvps.Array.1.defaultEn", "I woaß, dass mia wos verfoigt.\nOwa i hom’s Gfühl, dass i imma wieda duach\nde glechn Raam tanz.\nHoffentlich beweis’n de Notitzn, de i wia\nBrotkrum hinterließ, dass i Fortschritt mach\nund i iwgendwann a Ziel erreich.\n\nI hoff nur, dass ma ned de Tint\nausgeht. I hob a schrecklich’n Durst ...", expected: "I know something is following me.\nBut I feel like I am prancing through\nthe same rooms over and over..\nHopefully leaving notes as breadcrumbs\nwill prove I am making progress and\nreaching some destination.\n\nI just hope I don't run out of ink.\nI am dreadfully thirsty...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2699867187143063811, "kvps.Array.2.defaultEn", "Tinte...\nStillt mein Duascht ned wirkli.\nDa Gschmack is ungeniaßboa, de Fleckn san schrecklich.\n\nI glaab ned, dass des a bsonders\nromantische Idee woa,\ndes zum trinken.", expected: "Ink...\nNot quite quenching my thirst.\nTaste is terrible, stains are terrible.\n\nI don't think drinking it was\na very romantic idea.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2699867187143063811, "kvps.Array.3.defaultEn", "I hob heid wos g’fundn,\n zum Stilla von meim unromantischen Durscht.\n I bin heid aufgwacht ausm kurzn Ohnmachtsschlof,\n und hob vor mir a Flaschl\n Rotbier g’fundn!\n\n I woaß ned genau, wos für a Marke oder Jahr,\n denn es gibt koan Aufkleber.\n Alles, wos i g’schnappt hob,\n is, dass’s a richtig\n metallischen G’schmack hot.", expected: "I found something today to\nsatisfy my unromantic thirst.\nI awoke today from a brief faint,\nand found before me a bottle of\nred wine!\n\nI am not sure what brand or year,\nfor there is no label. All I\ngather is that it tastes strongly\nmetallic.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2699867187143063811, "kvps.Array.4.defaultEn", "I glaab ned, dass des Bier woa...", expected: "I don't think that was wine...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2699867187143063811, "kvps.Array.5.defaultEn", "I woaß ned, wie lang\ni no dorchhoitn ko…\n\nI hob koane vo mei frührn\nNotitzn gseng, des hoisst oiso\ndass i wos erreiche\noda des oa deepart sie mitnimmt.", expected: "I don't know how much longer\nI can go on...\n\nI haven't seen any of my\nprevious notes, so that means\neither I'm getting somewhere\nor someone is taking them.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2699867187143063811, "kvps.Array.6.defaultEn", "I denk dass des ma letzte Notiz is.\nI wird sterben ohne dos\ni ma Ausweg gefunden hob, aber \ndes stimmt ned. Dieser ort war wie ma\nAusweg. Ma Ausweg von all\nanderen quatsch. am ende is ma Tot scho\nromantisch.", expected: "I think this is my last note.\nI'm going to die having never\nfound my escape, but really that's\nnot true. This place was like my\nescape. My escape from everything\nelse. In the end my death is kind of\nromantic.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.0.defaultEn", "Braucht a Schlüsselkart’n", expected: "Needs A Keycard", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.1.defaultEn", "G'schlossen", expected: "Locked", inner: "CAB-165353818100901025e074d2c5e2b786"),
