        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.8.defaultEn", "Pumpen nei gstartet", expected: "Restarted Pumps", inner: "CAB-165353818100901025e074d2c5e2b786"),
