        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.10.defaultEn", "D’Laterne is aus", expected: "The lantern got snuffed out", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.11.defaultEn", "Neistarten", expected: "Restart", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.12.defaultEn", "Es is z’dunkl zum Seh’n", expected: "It's too dark to see", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.13.defaultEn", "D’Wossa steht z’hoch", expected: "The water's too high", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.14.defaultEn", "Schlüssel nemma", expected: "Pickup Key", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.15.defaultEn", "Schlüssel nemma", expected: "Pickup Key", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.16.defaultEn", "Schlüssel gnumma", expected: "Got Key", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.17.defaultEn", "I soi z’erscht amoi umguggn", expected: "I should look around first", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.18.defaultEn", "Blockiert", expected: "Blocked", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.19.defaultEn", "Z’brochn", expected: "Broken", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.20.defaultEn", "I muaß mi versteck’n!", expected: "I need to hide!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.21.defaultEn", "Geht ned", expected: "It's out of order", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.22.defaultEn", "vom Acker mach’n", expected: "Leave", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.23.defaultEn", "Das Buch gnumma", expected: "Picked up the book", inner: "CAB-165353818100901025e074d2c5e2b786"),
