        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.36.defaultEn", "Nimm d’Axt", expected: "Take Axe", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.37.defaultEn", "Drück’n", expected: "Press", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.38.defaultEn", "Musik mach’n", expected: "Play", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.39.defaultEn", "Neistarten", expected: "Reset", inner: "CAB-165353818100901025e074d2c5e2b786"),
