        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.42.defaultEn", "OASSN", expected: "CONSUME", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.43.defaultEn", "Guad", expected: "Delicious", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.44.defaultEn", "Nimm’s Schwert", expected: "Get Sword", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 2874833270264989338, "kvps.Array.45.defaultEn", "Schwert kriagt", expected: "Got Sword", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3020247333765276334, "kvps.Array.0.defaultEn", "I glaab, Zipfel 5 is entkemma.\r\nDes Glos um sei Gfängnis is zbrocha,\r\nund i hör leise Klickgeräusch vo\r\nda Deck’ herunna. I woaß ned, wos\r\njetzt passiern wird. Wenn’s draußa\r\nis und lebt, dann is des woscheinlich\r\nmei letzta Bericht.\r\nDes Geklick wird jetzt lauter.\r\n\r\n      – Allgemeina Laborassistent", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3020247333765276334, "kvps.Array.1.defaultEn", "Subjekt 5 wird imma unruhiger.\nI hob Spooky gsogt, dass ma\nmehra Gelt für Beruhigungsmittel\nbrauchan, owa sie hod nur glocht\nund is an d’Deck’ gfloga. Ohne\nmehra Drogen, um de Wesn ruhig\nz’hoita, bin i mir ned sicha,\nwie lang ma’s no sicha hier\nbehoiden kenna.\n\n          – Generischer Laborassistent", expected: "Subject 5 is growing more and\nmore restless. I told Spook we\nneed more funds for sedatives,\nbut she just laughed and flew\ninto the ceiling. Without more\nchemicals to keep these things\ndocile, I'm not sure how much\nlonger we can keep them here\nsafely.\n\n          - Generic Lab Assistant", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3229508212047837832, "text", "Spritz’n, Platschn, geleeartig.\n\nInnerein, Fress’n, Beschwören.\n\nNageln, Nie, hört’s Würgen ned aaf", expected: "Spouting, Splashing, Soaking.\n\nInnards, Ingest, Invoking.\n\nNailing, Never, Stops the Choking", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3469927114304250625, "kvps.Array.0.defaultEn", "Das alte GL-Labs is irgendwie\r\nno schlechta wia’s neie.\r\nObwohl’s ausschaun tuat\r\nois hätt’s mit a großerer Buidget 'baut worn\r\nfunktionierts nimma ganz.\r\nI ko scho vasteihn\r\nwoswegen’s so schnei\r\n aufg’gebn worn is.\r\nI frag mi, ob’s do\r\n iwaubhaupt wos zom Rettn gibt.", expected: "This old place is somehow\r\neven worse than the new\r\nGL Labs. Although it seems \r\nto have been constructed\r\nwith a much larger budget than\r\nthe new lab, nothing works\r\nquite right. I can see why it\r\nwas abandoned so quickly.\r\nI wonder if there really is \r\nanything here worth salvaging.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3469927114304250625, "kvps.Array.1.defaultEn", "Dese Einrichtung is ziemli komisch.\r\nA Teil vo de Ausrüstung scheint\r\nned ganz richdig zo sein,\r\nois hätt’s fia Leid ohne Hände\r\nkonstruiert worn sei…\r\nI bin ma au ned sicha\r\nob's de geräte san die\r\nned genggan\r\nOwa de Stroom schwankt und es\r\n kimman komische G’räuschn\r\n aus de Lüftungsschächtn.", expected: "This facility is quite odd. Some\r\nof the equipment doesn't seem\r\nquite right, almost as if it were\r\ndesigned for people without\r\nhands... \r\n\r\nAlso I'm not sure if it's just \r\nfaulty electronics, but the\r\npower keeps fluctuating and\r\nweird noises are coming \r\nfrom the air ducts.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3469927114304250625, "kvps.Array.2.defaultEn", "Spooky hod grod g’sogt, dass do \r\n„Dinga“ gibt, de mia aus dem\r\noad rettn miassn.\r\nI fang a, mi sorgn zomoch’n\r\nob a  Zipflklatscher aa bei de\r\n„Dinga“ dabei is,\r\nde mia hoin missa.\r\nDer Stroom is wieda ausg’foin.\r\nIs ois do kaputt?", expected: "Spooky just said that there \r\nwere 'things' we needed to\r\nsalvage from this place. I'm\r\nstarting to worry that a loose\r\nspecimen may be included\r\nin the list of 'things' for us\r\nto retrieve. \r\n\r\nThe power just shut off\r\nagain. Is everything broken\r\nin here?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3469927114304250625, "kvps.Array.3.defaultEn", "I woaß ned, wos i toa soi.\nI ko ned gscheit denka\nmir is so komisch.\nI versteck mi vor dem Zipfel.\nMir is, als wia wanns ma wos\nauf da Haut wachst.\n\n\nI bring's ned schnei gnug oba,\nund i valier\na Haufn Bluad...", expected: "I don't know what to do.\nI can't think well, I feel\nstrange. I'm hiding from\nthat thing.\n\n\nI feel like something is\ngrowing on my skin.\n\n\nI can't seem to tear it\noff fast enough, and I'm\nlosing a lot of blood...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3469927114304250625, "kvps.Array.4.defaultEn", "Du musst den Zipfel nah bei dir hoitn.\nEs werd wos andas\nwenn's z'weit weg kimmt.\n\n\nEtwos, vor dem i ned davonrennan ko.", expected: "You have to keep it close.\nIt becomes something else\nwhen it gets too far away.\n\n\nSomething I can't out run.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3606552722643987134, "kvps.Array.0.defaultEn", "Zipfelklatscher 3", expected: "Specimen 3", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3606552722643987134, "kvps.Array.1.defaultEn", "macht oan schmoan\nIn Entwicklung\r", expected: "Active/ In Testing\r", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3606552722643987134, "kvps.Array.2.defaultEn", "Dreckige Biss’n", expected: "Infectious Bites", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 3606552722643987134, "kvps.Array.3.defaultEn", "A Test-Zipfelklatscher, wos grad im GL-Labora zücht’n. Sollt scho nützlich sei, wenn ma’n amoi auslossn. De Versuach ham g’zeigt, dass a recht wirksam is – zumindst bei de durchschnittlich’n Leit.", expected: "A test specimen being developed at GL Labs. Should prove useful when released. Trials have shown it is adequately effective  to average subjects.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4115212064835762163, "kvps.Array.0.defaultEn", "Zipfelklatscher 11", expected: "Specimen 11", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4115212064835762163, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4115212064835762163, "kvps.Array.2.defaultEn", "Nur Gott weiß, mia aba ned", expected: "Unknown", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4115212064835762163, "kvps.Array.3.defaultEn", "A schwebende rote Gstalt, de unterm grodn, oamoligen Firmengebäude vo ana Restaurantkett gfundn wurn is, wo a geheimen Beziak hod. Der Zipfel is äußerst gewolttätig und schein, obwoi verschiedene Eindämmungsmaßnahmen, des Gebeid noch Belieng z’verlassen. Bei Kontakt mit dem Zipfel verschwinden de Opfer, owa mol wurn Tage spieter Nochste von de Opfer in da Testkamma gfundn.\n\nEs hod si ois unwiaksum erwisn, da dei de Seelen vo de Opfer nochm Kontakt net zruckbleim.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4317078113098548725, "kvps.Array.0.defaultEn", "Zerscht sah da Ort niedlich aus,\r\naba i bin scho seid Tagen do …\r\nI fühl mi jetzt rechd ausgetrocknet, und\r\nI hob ständig des Gfühl, dass i vo\r\nwos beobocht wern.\r\n\r\nDes is überhaupt ned romantisch ...", expected: "At first this place just seemed cute,\nbut I've been here for days now...\nI'm feeling quite parched now, and\nI keep getting this feeling like I am\nbeing watched by something.\n\n\nThis is not romantic at all...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4317078113098548725, "kvps.Array.1.defaultEn", "I woaß, dass mia wos verfoigt.\nOwa i hom’s Gfühl, dass i imma wieda duach\nde glechn Raam tanz.\nHoffentlich beweis’n de Notitzn, de i wia\nBrotkrum hinterließ, dass i Fortschritt mach\nund i iwgendwann a Ziel erreich.\n\nI hoff nur, dass ma ned de Tint\nausgeht. I hob a schrecklich’n Durst ...", expected: "I know something is following me.\nBut I feel like I am prancing through\nthe same rooms over and over..\nHopefully leaving notes as breadcrumbs\nwill prove I am making progress and\nreaching some destination.\n\nI just hope I don't run out of ink.\nI am dreadfully thirsty...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4317078113098548725, "kvps.Array.2.defaultEn", "Tinte...\nStillt mein Duascht ned wirkli.\nDa Gschmack is ungeniaßboa, de Fleckn san schrecklich.\n\nI glaab ned, dass des a bsonders\nromantische Idee woa,\ndes zum trinken.", expected: "Ink...\nNot quite quenching my thirst.\nTaste is terrible, stains are terrible.\n\nI don't think drinking it was\na very romantic idea.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4317078113098548725, "kvps.Array.3.defaultEn", "I hob heid wos g’fundn,\n zum Stilla von meim unromantischen Durscht.\n I bin heid aufgwacht ausm kurzn Ohnmachtsschlof,\n und hob vor mir a Flaschl\n Rotbier g’fundn!\n\n I woaß ned genau, wos für a Marke oder Jahr,\n denn es gibt koan Aufkleber.\n Alles, wos i g’schnappt hob,\n is, dass’s a richtig\n metallischen G’schmack hot.", expected: "I found something today to\nsatisfy my unromantic thirst.\nI awoke today from a brief faint,\nand found before me a bottle of\nred wine!\n\nI am not sure what brand or year,\nfor there is no label. All I\ngather is that it tastes strongly\nmetallic.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4317078113098548725, "kvps.Array.4.defaultEn", "I glaab ned, dass des Bier woa...", expected: "I don't think that was wine...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4317078113098548725, "kvps.Array.5.defaultEn", "I woaß ned, wie lang\ni no dorchhoitn ko…\n\nI hob koane vo mei frührn\nNotitzn gseng, des hoisst oiso\ndass i wos erreiche\noda des oa deepart sie mitnimmt.", expected: "I don't know how much longer\nI can go on...\n\nI haven't seen any of my\nprevious notes, so that means\neither I'm getting somewhere\nor someone is taking them.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4317078113098548725, "kvps.Array.6.defaultEn", "I denk dass des ma letzte Notiz is.\nI wird sterben ohne dos\ni ma Ausweg gefunden hob, aber \ndes stimmt ned. Dieser ort war wie ma\nAusweg. Ma Ausweg von all\nanderen quatsch. am ende is ma Tot scho\nromantisch.", expected: "I think this is my last note.\nI'm going to die having never\nfound my escape, but really that's\nnot true. This place was like my\nescape. My escape from everything\nelse. In the end my death is kind of\nromantic.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4350653267599487156, "kvps.Array.0.defaultEn", "DER_DELFIN", expected: "THE_DOLPHIN", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4350653267599487156, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4350653267599487156, "kvps.Array.2.defaultEn", "Beißn", expected: "Biting", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4350653267599487156, "kvps.Array.3.defaultEn", "A plastischer Chirurg, der no am Schwimmerlebnis mit Delfine fasziniert war. Der is dann auffa Idee kemma, si selber zu operiern, um mehra wia a Delfin auszsehn. Irgendwann is er dann in a übaflossne Höhle gfundn worn.\n\nDer is äußerst effektiv, wenn’s drum geht, Probanden komplett zu verwirrn und ihnen a Gänsehaut zu jagn.", expected: "A plastic surgeon who became infatuated with dolphins after a swimming experience. The surgeon then operated on himself to appear more dolphin like and was found living inside a flooded cave.\n\nProved extremely effective at making subjects utterly confused and creeped out.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4715000640392111156, "kvps.Array.0.defaultEn", "DOG #2\r\n\r\nToilleten stinken wie sau.\r\nBier is fast nimma do.\r\nUnd ich muss dringend raus, \r\nI dua o boa Notizen hinterlassen damit i woaß wo i scho war.", expected: "DAY 2.\r\n\r\nFood supply depleted.\r\nWater supply at 30%.\r\nMental health deteriorating, \r\nleaving notes behind to help \r\nothers and mark where I've been.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4715000640392111156, "kvps.Array.1.defaultEn", "DOG #3\r\n\r\nI sah mal ein reh\r\noda wars doch wos andars? Der \r\nZipfel hat mich beinahe gegessn \r\nDoch i konnt ihn mit etwos schmackes vertreiben\r\nJo i bin der beste!", expected: "DAY 3.\r\n\r\nHallucinations are manifesting \r\nat increasing intervals. The \r\ncause is probably sleep \r\ndeprivation or a gas that is \r\nbeing pumped into the rooms.\r\n\r\nI have not yet been injured so \r\nI don't think the cause is a \r\nbrain injury or blood clot.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4715000640392111156, "kvps.Array.2.defaultEn", "DOG #4\r\n\r\nI hob vagessn wos fia deppat i bin\r\n warum bin i do?\r\n\r\nHier san eh nur hungrige Zipfel \r\ndie mi fressn woin \r\nlieber wärs mit aan Planierraupe alles zu vernichten.", expected: "DAY 4.\r\n\r\nI'm starting to lose track \r\nof time. \r\n\r\nThe battery on my phone \r\nbecame very low so I \r\ndelegated to save it in \r\ncase I find an exit.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4715000640392111156, "kvps.Array.3.defaultEn", "DOG #5\r\n\r\nI woaß nimma. \r\nWarum zum teifel bin i hier? \r\n\r\nGob es ann grund?\r\n\r\nI glaab der Vater im Himmel\r\nkimmt gleich zu mia. De\r\nhalluzinationen macha aua aua,\r\nI hob koa Bier nedda, \r\nI bin so weid von Minga \r\nI wui wieda do hi.", expected: "DAY 5.\r\n\r\nI can't remember. \r\nWhy did I come here? \r\n\r\nWas there ever a purpose?\r\n\r\nI believe death is steadily\r\napproaching me now. The\r\nhallucinations can hurt me,\r\nI'm out of provisions, \r\nand I'm having sudden \r\nviolent heart palpitations.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 4715000640392111156, "kvps.Array.4.defaultEn", "DOG #7\r\n  \r\nLiaba Gott im himmel dua mia oan \r\ngfalln. Falls i jetztat sterben sollte \r\nmach mi bitte zu an Geist. I miass \r\nDen spieler angucka \r\nund mit iam gerne sprecha \r\ndann hob i gsellschofft.\r\n\r\nNun bleib i do und spui so kloane speilchen \r\nbevor i weida genga.I woaß dos i \r\nwahrscheinlich verfolgt werd. \r\n\r\nAber mia wurscht. \r\nDiese Wiecheier und dieser Ort, \r\nkenna mia am osch lecka \r\ni werd glaab i den Ausgang findn \r\nin diesa Irrenhaus.\r\n\r\nWerd erstmoi ausruha.\r\nUnd über di vielleicht gucka.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5062067516839061240, "kvps.Array.2.defaultEn", "Język bawarski", expected: "Angielski", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5179299386368120003, "kvps.Array.0.defaultEn", "Zipfelklatscher 5", expected: "Specimen 5", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5179299386368120003, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5179299386368120003, "kvps.Array.2.defaultEn", "Nur Gott weiß, mia aba ned", expected: "Unknown", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5179299386368120003, "kvps.Array.3.defaultEn", "A Zipfel, den wo ma in da Kirchn vo am kloan Kaffl gfundn hod. De Leit san weg noch'm Kontakt mid dem Exemplar. Wia ma den Zipfel umbringt, woas ma no ned. Hod si ois extrem guad erwiesen geng Leit mid psychische Probleme oda an schwochn Willn.", expected: "A creature found inside the church of a small town. Subjects are lost after contact with the specimen. Current\r method of killing is unknown. Proved extremely effective against subjects with mental issues or weak wills.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5528364549726873138, "kvps.Array.0.defaultEn", "Zipfelklatscher 13", expected: "Specimen 13", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5528364549726873138, "kvps.Array.1.defaultEn", "Macht oan schmoan", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5528364549726873138, "kvps.Array.2.defaultEn", "aadringa\r", expected: "Drowning\r", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5528364549726873138, "kvps.Array.3.defaultEn", "A uraltes Wassawesen, des ois verlorene Seele gilt, de währand da Sintflut auf tragische Weis gstorbn is. Hod si ois äußerst wiaksam erwisn gega Personen, di ned schwimma konntn oda auf an Köder vom Zipfel hereingfoin san.\r", expected: "An ancient water dwelling creature believed to be a lost soul who died tragically during the Deluge. Proved extremely effective against subjects that could not swim or fell for the specimen's lure.\r", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5633464982509913345, "kvps.Array.0.defaultEn", "Zipfelklatscher 2", expected: "Specimen 2", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5633464982509913345, "kvps.Array.1.defaultEn", "Macht oan Schmorrn", expected: "Active", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5633464982509913345, "kvps.Array.2.defaultEn", "Körper völlig zamreissn\r", expected: "Physical Tearing\r", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5633464982509913345, "kvps.Array.3.defaultEn", "A g’mocht’s G’spenst, des größtenteils aus so halbfestem Zeig besteht und dauernd sei Zustand ändert. Hod si als recht wirkungsvoll gegenüber de schwächern oder langsamern Opfer rausgstellt.", expected: "A mostly semi-solid based specter that frequently changes matter states. Proved very effective against weaker or slower subjects.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5920510614232101344, "kvps.Array.1.defaultEn", "in Entwicklung", expected: "In Development", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5920510614232101344, "kvps.Array.2.defaultEn", "Nur Gott weiß, mia aba ned", expected: "Unknown", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 5920510614232101344, "kvps.Array.3.defaultEn", "A kloanes mädl, vo dem ma glaabt, dass es irgendwia was mid da Gschicht vom 'Pied Piper' z'toa hod und si in vaschiedene grauslige Formen verwandlt,\n\ndamit da Bosskampf länga dauert. Is no in da Entwicklung, hot oba bei gwissn Mitaboata scho guat gwirkt.", expected: "A young girl that is believed to be somehow related to the 'Pied Piper' story and changes into various horrific forms to drag out the boss battle.\n\nIn development but has proved effective on certain staff.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6744129680267076402, "kvps.Array.0.defaultEn", "So lang wia ma si zurückerinnern kinnt, werdn Gschichten über de verfallene Villa ob’m Berg vazeihlt, de a Decke aus Dunkelheit über d’Stod legt. De Gschichtn vom Haus selber san praktisch unbekannt, und a de oidsten Leit im Dorf kennen si ned, woher de Villa eigentlich kimmt. Du, a richtiga G’schichtsfan, steigst drauf auf’n Berg, um’s Anwesen z’besuchn. In da Hoffnung, a weng Licht auf de Vorgschicht von dem zerfallenen Schloss vo da Dunkelheit zu werfn.\n\n", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.0.defaultEn", "Weitermacha", expected: "Continue", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.1.defaultEn", "Ausschdeing", expected: "Exit", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.2.defaultEn", "Neies Spui", expected: "New Game", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.3.defaultEn", "Optionen", expected: "Options", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.4.defaultEn", "Aktions-Gruppe", expected: "Action Group", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.5.defaultEn", "Übernemma", expected: "Apply", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.6.defaultEn", "Drück irgendan Knopf oder beweg an Stick. Wird in {0:F1} Sekund’n abbrochn.", expected: "Press a button or move a stick on this device. Cancels in {0:F1}s", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.7.defaultEn", "Bindung {0}", expected: "Binding {0}", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.8.defaultEn", "Abbrecha", expected: "Cancel", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.9.defaultEn", "Bestätiga", expected: "Confirm", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.10.defaultEn", "Grafikeinstellungen bestätigen", expected: "Confirm graphics changes", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.11.defaultEn", "Bist da sicha, dass’d ois auf d’Werkseinstellunga z’rücksetzn wüst?", expected: "Are you sure you want to reset to default settings?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.12.defaultEn", "Sichtfeld*", expected: "Field of View*", inner: "CAB-165353818100901025e074d2c5e2b786"),
