        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.21.defaultEn", "Entfern’n", expected: "Remove", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.22.defaultEn", "Auf Voreinstellungen zurückstellen", expected: "Reset To Defaults", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.23.defaultEn", "Auflösung*", expected: "Resolution*", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.24.defaultEn", "D’Eistellungen werdn in {0:F1} zruckgsetzt", expected: "Settings revert in {0:F1}", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.25.defaultEn", "Zipflklatscher", expected: "Specimen", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.26.defaultEn", "Oustellunga", expected: "Options", inner: "CAB-165353818100901025e074d2c5e2b786"),
