        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.28.defaultEn", "Lärm", expected: "Volume", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.30.defaultEn", "* Wirkt ned auf VR", expected: "* Doesn't affect VR", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.31.defaultEn", "ins Menü genga", expected: "Exit to Menu", inner: "CAB-165353818100901025e074d2c5e2b786"),
