        Mod.SetString("StreamingAssets/mansionroomdefs", 6771480481796675210, "kvps.Array.57.defaultEn", "NOTE: Unterstützung fürs Neuzentrieren hängt stark vom Gerät ab. Wenn’s ned klappt, hod dein Gerät vielleicht a andere Vorgehensweise.", expected: "NOTE: Recentering support varies widely between devices. If this doesn't work your device may have a different procedure.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.0.defaultEn", "Griaß di, I bin Spooky!", expected: "Hello, I am Spooky!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.1.defaultEn", "Und des is ma Zuhaus.", expected: "And this is my home.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.2.defaultEn", "Konst, du demütiga Spuiar,", expected: "Can you, humble player,", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.3.defaultEn", "durch a tausend Zimma kemma?", expected: "make it through a thousand rooms?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.4.defaultEn", "Konst du herausfinda, wos am End liegt?", expected: "Can you find, what lies at the end?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.5.defaultEn", "Oda gibt’s überhapt a End?", expected: "Or is there even an end?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.6.defaultEn", "Weil i’s eigentlich ned wirklich woaß", expected: "Cuz I don't really know.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.7.defaultEn", "Wurscht, ge.. geeh eifoch.", expected: "Anyway, just.. just go.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.8.defaultEn", "ja mei! a Hund bist fei scho,\ndo host’s bis do hi g’schafft.", expected: "So, you made it this far.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.9.defaultEn", "Des is eh… des is großartig!", expected: "That's uh... that's great!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.10.defaultEn", "I werd da a G’schenk geba!", expected: "I shall grant you a gift!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.11.defaultEn", "Fia dei… Fortschritt.", expected: "For your... progress.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.12.defaultEn", "Na, äh… geh hoit weiter, oida.", expected: "So uh.. So just keep going.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.13.defaultEn", "Na, servus. Host di valaf’n, du kloans Wiaschtl?", expected: "Well hello there. Are you lost, little one?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.14.defaultEn", "Da Ort do konn dene helfa, de aa wirklich soweit san,\naber du konst mit mea Unruh rechna, ois’d gwohnt bist.", expected: "This place can help those who are ready,\nbut expect turmoil more than you are used to.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.15.defaultEn", "D’Maskn, wo’d aufhobst, duad scho ihr’n Dienst,\naber pass aaf, dass’d di ned in ihr valierst.", expected: "The mask you wear serves its purpose well,\nbut be careful not to lose yourself in it.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.16.defaultEn", "Zwoa Seitn von da semm Münz.\nWennst dei eigne Spieglungn kenst, konnst frei wern.", expected: "Two sides of the same coin.\nKnowing your projections can help you achieve freedom.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.17.defaultEn", "G’leichg’wicht is da Schlüssel,\ndamit dei Kopf frei und g’sund bleibt.", expected: "Balance is the key to keeping\nyour mind free and sane.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.18.defaultEn", "Wens dei Schattn kenst, ko des vui helfn\naber sei bereit, z’seng,\nwosd liaba ned mägst.", expected: "Knowing your shadow can greatly help\nyou, but be ready to see what\nyou'd rather not be.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.19.defaultEn", "Na, schau' ma's an.", expected: "Well, here you are.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.20.defaultEn", "bist am Leben und... immer noch hier.", expected: "Alive and... still here.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.21.defaultEn", "Du bleibst am Ball, ned?", expected: "You just keep on going, don't you?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.22.defaultEn", "De nächste Tür is für di scho repariert.", expected: "Well the next door has been fixed up for you.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.23.defaultEn", "Na dann pack ma's und kim guad o!", expected: "So enjoy, and keep moving on!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.24.defaultEn", "Du klena ... Weißwurschtlliches, lebendiges Ding.", expected: "You little... fleshy, live one.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.25.defaultEn", "O mei! I hätt nie glaabt, dass'd so weit kimmst! Ja leck mi am Schuah!", expected: "O hai, I didn't think you'd make it this far.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.26.defaultEn", "Ja, sakrisch! Und a Axt host aa?", expected: "And you got an axe?", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.27.defaultEn", "Fei guad", expected: "Nice", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.28.defaultEn", "Na dann… gratuliere, ma Herr oda Frau!", expected: "Well congratulations!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.29.defaultEn", "Jo, fast bist do... glaab i hoit.", expected: "You're just about there... I think.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.30.defaultEn", "Na ja, a Gschenk hob i eigentli ned g’macht, also…", expected: "Well I didn't really have a gift ready so... uh..", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.31.defaultEn", "SCHAAA!", expected: "SHAAA!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.32.defaultEn", "Na, do host’s, unbegrenzta Ausdauer!", expected: "There you go, unlimited stamina.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.33.defaultEn", "Des werd nieamois, nieamois aufg’hörn!", expected: "It'll never ever run out.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.34.defaultEn", "Jo, dann seng ma uns späta!", expected: "So... See you later!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.35.defaultEn", "Du host's gschafft.", expected: "Well you made it.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.36.defaultEn", "Herzlichen Glückwunsch.", expected: "Congratulations.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.37.defaultEn", "I glaab.", expected: "I guess.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.38.defaultEn", "Öhm. nun...", expected: "Uh. Well...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.39.defaultEn", "Ah!", expected: "Oh!", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.40.defaultEn", "So, du musst jetzt noch a letzte Prüfung besteha, um dei...", expected: "So, you must now pass one final test to prove your...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.41.defaultEn", "Standhaftigkeit oda Einsatz zu beweisen.", expected: "Fortitude or dedication.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.42.defaultEn", "Oder so wos..", expected: "Or something..", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.43.defaultEn", "Naa vui Glück klena Weißwurschtl.", expected: "Well good luck little fleshy one.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.44.defaultEn", "I sammel de ‘Holzstammal’, de’s allweil ausschmeiß’n…", expected: "I'm taking all those 'logs' they keep throwing out...", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7206572898034996203, "kvps.Array.45.defaultEn", "Und i nagl’s z’samm..", expected: "And I'm nailing them together..", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 7471878311913830621, "kvps.Array.2.defaultEn", "Ваварский язык", expected: "Английский", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 9181355560742157563, "kvps.Array.0.defaultEn", "Eines Tages is a seltsamer Händla\r\nin d’Stadt kemma. Der hod\r\nhandgschaffene Puppn und\r\nSchmuckstucke verkauft\r\nund olle Kinda hom sei Lodn\r\nund seine Gschenke g’liebt.\r\nOwa d’Stadt hod sei Laden ned\r\nunterstützn kenna,\r\nweil de andan Geschäfte schlecht\r\ng’laafa hom.\r\n\r\nDe andan Ladenbesitza\r\nhom s’neidisch g’mocht.\r\nAlso hom a paar Dorfbewohner\r\noa nocht olle sei Puppn\r\ng’nomma und\r\nin den Fluss g’worfen.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 9181355560742157563, "kvps.Array.1.defaultEn", "Doch kurz drauf is er\nweinend und kloagand zua\nFluss g’rannt, dass sei Kinder\nertrunken wern. Er is in den Fluss\ng’sprunga, um sei Eigentum z’rettn.\n\n\nDe Stadtbewohner, verbittat\nund immer no wütend,\nhom z’g’schaut, wia er\nverzweiflt um si g’schlogn und\nin den Fluss g’tauft is,\nbis er nie wieder obi kemma is.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 9181355560742157563, "kvps.Array.2.defaultEn", "Obwoi’s ned des woarn is, wos se g’woit hom\n, hom de Ladenbesitza\n sie g’freut g’habt.", expected: "Although not what they\nwanted, the shop keepers\nwere satisfied.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionroomdefs", 9181355560742157563, "kvps.Array.3.defaultEn", "Joare späda hom de Kinda\r\nda Stadt oifach z’verschwinden ofangt.\r\nUnd je mea\r\nKinder verschwunden san\r\n, desto mea Puppn hom\r\nde Leit’ im Woid und uman Fluss g’fundn.\r\n\r\nDe Puppn hom ma mol\r\nfast wia de vermissten\r\nKinda ausgschaugt.", expected: "Years later the children\r\nof the town began to go\r\nmissing. And as more\r\nand more children \r\ndisappeared, people\r\nbegan to find more and\r\nmore puppets in the\r\nforest and around the \r\nriver.\r\n\r\nThese puppets seemed\r\nalmost to look like the \r\nmissing children sometimes.", inner: "CAB-165353818100901025e074d2c5e2b786"),
        Mod.SetString("StreamingAssets/mansionrooms", 3616, "m_text", "Neia Rekord!", expected: "New High Score!", inner: "BuildPlayer-mini_room"),
        Mod.SetString("StreamingAssets/mansionrooms", 3617, "m_text", "Mia stella...\n     ...paar <color=#9EEBFF>Gspensta vor!</color>", expected: "Introducing...\n     ...some <color=#9EEBFF>ghosts!</color>", inner: "BuildPlayer-mini_room"),
        Mod.SetString("StreamingAssets/mansionrooms", 3618, "m_text", "Drück a Knopf", expected: "Press Button To Start", inner: "BuildPlayer-mini_room"),
        Mod.SetString("StreamingAssets/mansionrooms", 3624, "m_text", "Level 1", expected: "Stage 1", inner: "BuildPlayer-mini_room"),
        Mod.SetString("StreamingAssets/mansionrooms", 3762, "introGhosts.Array.0.ghostIntroText", "Zerscht is <color=#65CAFF>Edgar</color>. er ist a bisal trostlos!", expected: "First up is <color=#65CAFF>Edgar</color>. He's kind of dreary!", inner: "BuildPlayer-mini_room"),
        Mod.SetString("StreamingAssets/mansionrooms", 3762, "introGhosts.Array.1.ghostIntroText", "Als nächsts ham ma, <color=#FF9A69>Mary</color> Is endlich aus irra Hülle kemma!", expected: "Next, <color=#FF9A69>Mary</color> finally came out of her shell!", inner: "BuildPlayer-mini_room"),
        Mod.SetString("StreamingAssets/mansionrooms", 3762, "introGhosts.Array.2.ghostIntroText", "Dritte is <color=#65FF65>Bram</color> und er is angheizt hier zu soa!", expected: "Third is <color=#65FF65>Bram</color> and he's stoked to be here!", inner: "BuildPlayer-mini_room"),
        Mod.SetString("StreamingAssets/mansionrooms", 3762, "introGhosts.Array.3.ghostIntroText", "Und endlich auf dea mia alle gwotet hom, es is <color=#B3EFF9>Spooky</color> selba!!!! !!!!!!!!!!!!", expected: "And finally what everyone's been waiting for it's <color=#B3EFF9>Spooky</color> herself!!!! !!!!!!!!!!!!", inner: "BuildPlayer-mini_room"),
