        Mod.SetString("StreamingAssets/mansionrooms", 571, "m_text", "ZURIACK", expected: "BACK", inner: "BuildPlayer-CAT_room"),
        Mod.SetString("StreamingAssets/mansionrooms", 572, "m_text", "Todesfälle: {0}", expected: "Total Fatalities: {0}", inner: "BuildPlayer-CAT_room"),
        Mod.SetString("StreamingAssets/mansionrooms", 573, "m_text", "PROGRAM_BEENDEN", expected: "EXIT_PROGRAM", inner: "BuildPlayer-CAT_room"),
        Mod.SetString("StreamingAssets/mansionrooms", 574, "m_text", "ZURIACK", expected: "BACK", inner: "BuildPlayer-CAT_room"),
        Mod.SetString("StreamingAssets/mansionrooms", 575, "m_text", "AUF_ZIPFEL_DATENBANK_ZUGREIFFA", expected: "ACCESS_SPECIMEN_DATABASE", inner: "BuildPlayer-CAT_room"),

        Mod.SetString("StreamingAssets/doll_scenes", 19, "m_text", "Scharlachrode, brennade Lecha wern auf d'Haut brennt\nund s'Fleisch hupft in a ganz fremde Form z'riack.\nZu wos Neim z'ammg'quetscht, de Husk nei g'staltet\nin a Haut, de de schreiande Lehre viel liaba aufnimmt.", expected: "Scarlet burning holes are placed onto the skin\nand flesh rebound into an unfamiliar form.\nMolded into something new, the husk reshaped\ninto a skin more accepting of the howling void.", inner: "BuildPlayer-HuskKillScene"),
        Mod.SetString("StreamingAssets/doll_scenes", 22, "m_text", "Brät in Brät windet und bläht si.\nDie groben Gewürze drängen unaufhaltsam nach außen\ngegen den Naturdarm, der sie eng umschließt.\nEs zieht und spannt, bis die Elastizität der Haut\nletztendlich kläglich versagt.\nDurch die kleinen Risse brechen die weißen Brät-Flocken endlich hervor. \n\nDu bist endlich frei von diesem einengenden Hautschlauch.", "Form within form writhes and pulses.\nSkeletal sinews stretch outward from\nbeneath the skin wrapped around it.\nIt pulls until the skin's elasticity\nfails ultimately. From these small holes\nthe tendrils of bone finally escape.\n\nYou are finally free of this constricted bag of flesh", "BuildPlayer-WoormyKillScene"),
        Mod.SetString("StreamingAssets/doll_scenes", 34, "m_text", "A \"ned-bayrischs\" Kind is in a Gruam gschmissn worn.\nKoa Tradition hods jemals kennalerna derfa.\n\nGstraft homs es, ohne Gnad und ohne Zögern.\nAls wia wenns recht gwesn war, vom Herrgott sejba.\n\nGerecht war des ned, es war ehrenlos, ja daiflisch.\nIrgendwann werns alle versteng, in da ewign Verdammnis.", "A \"wicked nasty\" child was thrown into a pit.\nNo food, light or water was ever given to it.\n\nPunishment was dealt, without mercy or hesitation.\nAs if justified by faith, or ownership from creation.\n\nIt was no righteous act, it was hellish, demon sent.\nEventually all will find out, in eternal torment.", "BuildPlayer-HookKillScene"),
        Mod.SetString("StreamingAssets/doll_scenes", 19, "m_text", "BLITZE REISSN DA D’HAUT VOMS GSICHT\nDA DAMPFNE SAFT IN DA GLUAD VERRICHT’\nDE BOANA BRENNA, ES RÜTTELT DI GSCHEID\nVERLASS DEI HÜLLN, ES IS SOWEIT", "ELECTRIC TETHERS TORN FROM SKIN\nGASEOUS BLOOD ESCAPES WITHIN\nBONES BEGIN TO BURN AND SHAKE\nLEAVE THE BODY THAT YOU FORSAKE", "BuildPlayer-ShockKillScene"),
        Mod.SetString("StreamingAssets/doll_scenes", 28, "m_text", "BIST NO GANZ SAUBER?!", "YOU ARE A FOOL.", "BuildPlayer-BurnKillScene"),
        Mod.SetString("StreamingAssets/doll_scenes", 33, "afterText", "DE BRANDBLODERN KOCHEN UND WOCHSN GSCHEID\nBIS D' HAUT ZAFOID UND SE ZERREISST\nAUS DE KLOANAN LIACHA KRIECHAT DE GLUAT\nHINEIN IN DA WÄID AUS FLEISCH UND BLUT \n\nDU BIST DA WEG FIA D' HÖLLE WORN.", "THE BURNS BOILED AND GROW UNTIL THEY BURST INTO TINY HOLES\nOF WHICH THEY COULD FINALLY CRAWL OUT\nINTO THIS WORLD.\n\nYOU HAVE BECOME THE GATEWAY.", "BuildPlayer-BurnKillScene"),
        Mod.SetString("StreamingAssets/doll_scenes", 22, "m_text", "DEI GESTALT WIRD ZU VAPUIVATN ASCHN", "YOU'RE FORM BECOMES AS TINY DROPLETS\nOF CHARRED WITHERED FLESH", "BuildPlayer-BoomKillScene"),

        Mod.SetString("StreamingAssets/specimen", 4504375178337192762, "kvps.Array.0.defaultEn", "Denkst du bist a gfeider\r\nfuchs ned?", "You think you're clever \r\ndon't you?", "CAB-9ced225ec81b66ef18bab3b5c977f9a2"),
        Mod.SetString("StreamingAssets/specimen", 4504375178337192762, "kvps.Array.1.defaultEn", "I beobacht di scho fia\nne lange Zeid.", "I've been watching you for\na while now.", "CAB-9ced225ec81b66ef18bab3b5c977f9a2"),
        Mod.SetString("StreamingAssets/specimen", 4504375178337192762, "kvps.Array.2.defaultEn", "Fia wos blost 'n dei\nLuftballon überhaupt no auf?", "Why even bother filling\nyour lungs?", "CAB-9ced225ec81b66ef18bab3b5c977f9a2"),
        Mod.SetString("StreamingAssets/specimen", 4504375178337192762, "kvps.Array.3.defaultEn", "Dei Lebenssaft riacht so dick.\nI ko d'Adern saftln hian.", "Your blood smells so thick.\nI can hear the vessels oozing.", "CAB-9ced225ec81b66ef18bab3b5c977f9a2"),
        Mod.SetString("StreamingAssets/specimen", 4504375178337192762, "kvps.Array.4.defaultEn", "Glaubst leicht, dei Trinität\nschützt di?", "Do you feel safe?", "CAB-9ced225ec81b66ef18bab3b5c977f9a2"),
        Mod.SetString("StreamingAssets/specimen", 4504375178337192762, "kvps.Array.5.defaultEn", "Diese Texte zu lesen wird di\r\n  \r\nned helfa nur dea Himmel duads.", "Reading these won't help you.\r\n  \r\nOnly death can help you.", "CAB-9ced225ec81b66ef18bab3b5c977f9a2"),

        Mod.SetString("StreamingAssets/doll_scenes", 3384, "m_text", "DOUG\n1964-1986\n\nGL LABS MITARBEITER", "DOUG\n1964-1986\n\nGL LABS ASSOCIATE", "BuildPlayer-DOLL_LAB"),
        
        //edit these
        Mod.SetString("StreamingAssets/doll_scenes", 3388, "m_text", "Doug! Mia gratuliern da! \n\nGL Labs hod di ausgwählt,\ndassst di freiwillig fia an\nSpezialauftrag meldest! \n\nMia schicka di diaf\nunta d’Eadn, dassd as\nGebiet fia unsa neie\nAbteilung ausgrobst. \n\nPass dort untn auf vor \nGspensta und oide Skelettn. \n\nVui Glück!", "Congratulations Doug!\n\nGL Labs has chosen you\nto volunteer for a\nspecial assignment!\n\nWe are sending you deep\ninto the earth to excavate\nthe area for our new\ndepartment.\n\nLook out for ghosts and\nold skeletons down there.\n\nGood Luck!", "BuildPlayer-DOLL_LAB"),
        Mod.SetString("StreamingAssets/doll_scenes", 3397, "m_text", "In Erinnerung an", "IN MEMORY OF", "BuildPlayer-DOLL_LAB"),
        Mod.SetString("StreamingAssets/doll_scenes", 3393, "m_text", "SPUIN", "PLAY", "BuildPlayer-DOLL_LAB"),
        Mod.SetString("StreamingAssets/doll_scenes", 3386, "m_text", "EWIGE", "RIP", "BuildPlayer-DOLL_LAB"),
        Mod.SetString("StreamingAssets/doll_scenes", 3390, "m_text", "", "IN", "BuildPlayer-DOLL_LAB"),
        Mod.SetString("StreamingAssets/doll_scenes", 3387, "m_text", "RUHE", "PEACE", "BuildPlayer-DOLL_LAB"),

